  1→/**
  2→ * Phase 3: トピック付け
  3→ *
  4→ * 切り出した大問画像(PNG)をGemini Visionに送り、
  5→ * マスターリストに存在する5階層トピックタグを付与する。
  6→ *
  7→ * 大問単体の画像を見せて判定する（全体PDFからではない）。
  8→ * thinkingLevel: HIGH で深く考えてトピック判定する。
  9→ *
 10→ * Explicit Context Caching を使い、マスターリスト+共通プロンプトを
 11→ * キャッシュして入力トークンコストを削減する。
 12→ */
 13→
 14→import { ThinkingLevel } from "@google/genai";
 15→import { askVisionWithImage, callWithRetry, extractJson, getClient } from "../lib/gemini.js";
 16→import {
 17→  getTopicsForSubject,
 18→  isValidTopic,
 19→} from "../constants/topic-master.js";
 20→import type { SplitResult, TagResult } from "../types.js";
 21→
 22→const modelName = process.env.GEMINI_VISION_MODEL ?? "gemini-3-flash-preview";
 23→
 24→const BASE_SUBJECT_TO_JA: Record<string, string> = {
 25→  math: "数学",
 26→  physics: "物理",
 27→  chemistry: "化学",
 28→  biology: "生物",
 29→  english: "英語",
 30→  japanese: "国語",
 31→};
 32→
 33→
 34→const TOPIC_SELECTION_RULES = `【トピック選択の粒度ルール - 厳守】
 35→以下のルールでトピックの数を絞り込んでください。タグは少なく正確に。
 36→
 37→1. 大問の核心テーマに直結するトピックのみ選択する
 38→   - ○ その問題を特徴づける物理現象・数学的手法（例：慣性力、エネルギー保存則、漸化式）
 39→   - × 解く過程で使うだけの基本ツール（例：力のベクトル図、v=v₀+at、仕事の定義）
 40→   判断基準：「このトピックを消したら問題の本質が変わるか？」→ 変わらないなら付けない
 41→
 42→2. 同じサブ単元（第4階層）のトピックは最も代表的なもの1つだけ選ぶ
 43→   - × 「v=v₀+at」と「x=v₀t+(1/2)at²」を両方 → ○ 等加速度直線運動の中で1つだけ
 44→   - × 「静止摩擦力」と「動摩擦力」と「最大摩擦力」を全部 → ○ 問題で主に扱う1つだけ
 45→
 46→3. 1つの大問につきトピックは1〜4個を目安とする（多くても5個まで）`;
 47→
 48→/**
 49→ * 科目キーをトピックマスター用の正規科目名に寄せる。
 50→ * 例: physics_di / physics_sys_sci_info -> 物理
 51→ */
 52→export function normalizeTopicSubject(subject: string): string {
 53→  if (getTopicsForSubject(subject).length > 0) return subject;
 54→
 55→  const base = subject.split("_")[0];
 56→  const normalized = BASE_SUBJECT_TO_JA[base];
 57→  return normalized ?? subject;
 58→}
 59→
 60→/**
 61→ * マスターリスト用のシステムインストラクション（キャッシュ対象）を構築する
 62→ */
 63→function buildCachedInstruction(subject: string, topicListStr: string): string {
 64→  return `あなたは大学入試の${subject}の問題を分析し、トピックタグを付与する専門家です。
 65→
 66→【重要なルール】
 67→- 以下のマスターリストに存在するパスのみを使用してください（5階層固定: 科目/分野/単元/サブ単元/トピック）
 68→- マスターリストにないパスは絶対に使わないでください
 69→- 複数のトピックにまたがる場合は複数返してください
 70→
 71→${TOPIC_SELECTION_RULES}
 72→
 73→- JSON配列のみを返してください。マークダウンのコードブロックは不要です。
 74→
 75→【マスターリスト】
 76→${topicListStr}
 77→
 78→例: ["${subject}/分野A/単元A/サブ単元A/トピックA","${subject}/分野B/単元B/サブ単元B/トピックB"]`;
 79→}
 80→
 81→export async function createTopicContextCache(params: {
 82→  /** displayName末尾に使う（例: "physics_di" や "物理"） */
 83→  cacheNameSuffix: string;
 84→  /** マスターリストの科目名（例: "物理"） */
 85→  topicSubject: string;
 86→  /** 5階層フルパスのトピック配列 */
 87→  topicList: string[];
 88→  /** Cache TTL (e.g. "300s") */
 89→  ttl?: string;
 90→}): Promise<{ name: string; totalTokenCount?: number }> {
 91→  const client = getClient();
 92→  const systemInstruction = buildCachedInstruction(
 93→    params.topicSubject,
 94→    params.topicList.join("\n"),
 95→  );
 96→
 97→  console.log("  📦 マスターリストをContext Cacheに登録中...");
 98→  const cached = await client.caches.create({
 99→    model: modelName,
100→    config: {
101→      contents: [
102→        {
103→          role: "user",
104→          parts: [{ text: systemInstruction }],
105→        },
106→      ],
107→      tools: [{ codeExecution: {} }],
108→      ttl: params.ttl ?? "300s",
109→      displayName: `kakomon-topics-${params.cacheNameSuffix}`,
110→    },
111→  });
112→  if (!cached.name) {
113→    throw new Error("Context Cache create returned no name");
114→  }
115→  return {
116→    name: cached.name,
117→    totalTokenCount: cached.usageMetadata?.totalTokenCount,
118→  };
119→}
120→
121→export async function deleteTopicContextCache(name: string): Promise<void> {
122→  const client = getClient();
123→  await client.caches.delete({ name });
124→}
125→
126→/**
127→ * 1つの大問画像に対してトピックタグを付与する
128→ */
129→export async function tagSingleQuestion(
130→  imagePng: Buffer,
131→  label: string,
132→  subject: string,
133→  cachedContentName?: string,
134→  topicList?: string[],
135→): Promise<string[]> {
136→  // labelはPDF由来の非信頼データのため、プロンプトインジェクション防止にサニタイズ
137→  const safeLabel = label.replace(/」/g, "");
138→
139→  // キャッシュ使用時・未使用時で共通のプロンプト前半部分
140→  const promptPrefix = `この画像は大学入試の${subject}の問題から「${safeLabel}」を切り出したものです。図中の数値や記号が小さい場合はズームして確認し、問題の内容を正確に把握してからトピックを判定してください。`;
141→
142→  // キャッシュ使用時はシンプルなプロンプト、未使用時はフルプロンプト
143→  let prompt: string;
144→  if (cachedContentName) {
145→    prompt = `${promptPrefix}この問題の出題分野のトピックタグをJSON配列で返してください。`;
146→  } else {
147→    const topicListStr = (topicList ?? []).join("\n");
148→    prompt = `${promptPrefix}
149→この問題の出題分野のトピックタグを付けてください。
150→
151→【重要なルール】
152→- 以下のマスターリストに存在するパスのみを使用してください（5階層固定: 科目/分野/単元/サブ単元/トピック）
153→- マスターリストにないパスは絶対に使わないでください
154→- 複数のトピックにまたがる場合は複数返してください
155→
156→${TOPIC_SELECTION_RULES}
157→
158→【マスターリスト】
159→${topicListStr}
160→
161→JSON配列のみを返してください。マークダウンのコードブロックは不要です。
162→
163→例: ["${subject}/分野A/単元A/サブ単元A/トピックA","${subject}/分野B/単元B/サブ単元B/トピックB"]`;
164→  }
165→
166→  const raw = await callWithRetry(() =>
167→    askVisionWithImage(prompt, imagePng, "image/png", cachedContentName, ThinkingLevel.HIGH),
168→  );
169→
170→  let tags: string[];
171→  try {
172→    tags = extractJson(raw);
173→  } catch {
174→    console.warn(`  ⚠ ${label} のタグパースに失敗: ${raw.slice(0, 200)}`);
175→    return [];
176→  }
177→
178→  // マスターリストに存在するパスのみを残す
179→  const validTags = tags.filter((t) => isValidTopic(t));
180→  const rejected = tags.length - validTags.length;
181→  if (rejected > 0) {
182→    const invalidTags = tags.filter((t) => !isValidTopic(t));
183→    console.warn(
184→      `  ⚠ ${label}: ${rejected}件のタグをマスターリスト照合で除外: ${invalidTags.join(", ")}`,
185→    );
186→  }
187→
188→  return validTags;
189→}
190→
191→/**
192→ * Phase 3: トピック付け
193→ *
194→ * 切り出し済みの大問画像群に対してトピックタグを付与する。
195→ * Explicit Context Caching でマスターリストをキャッシュし、
196→ * 入力トークンコストを削減する。
197→ */
198→export async function tagQuestions(
199→  splits: SplitResult[],
200→  subject: string,
201→): Promise<TagResult[]> {
202→  const topicSubject = normalizeTopicSubject(subject);
203→  const topicList = getTopicsForSubject(topicSubject);
204→  if (topicList.length === 0) {
205→    console.warn(`  ⚠ 科目「${subject}」（正規化: ${topicSubject}）のトピックがマスターリストに見つかりません`);
206→    return splits.map((s) => ({
207→      label: s.label,
208→      questionNumber: s.questionNumber,
209→      topicTags: [],
210→    }));
211→  }
212→
213→  console.log(
214→    `  🏷️  ${splits.length}個の大問にトピックタグを付与中（${topicSubject}: ${topicList.length}トピック）...`,
215→  );
216→
217→  // Explicit Context Caching: マスターリスト+共通プロンプトをキャッシュ
218→  let cachedContentName: string | undefined;
219→  try {
220→    const cached = await createTopicContextCache({
221→      cacheNameSuffix: subject,
222→      topicSubject,
223→      topicList,
224→    });
225→    cachedContentName = cached.name;
226→    console.log(
227→      `  📦 キャッシュ作成完了: ${cachedContentName} (${cached.totalTokenCount ?? "?"} tokens)`,
228→    );
229→  } catch (err) {
230→    console.warn(
231→      `  ⚠ Context Cache作成に失敗、キャッシュなしで続行: ${err instanceof Error ? err.message : err}`,
232→    );
233→  }
234→
235→  try {
236→    const results: TagResult[] = [];
237→
238→    for (const split of splits) {
239→      console.log(`  🏷️  ${split.label} タグ付け中...`);
240→      const topicTags = await tagSingleQuestion(
241→        split.imagePng,
242→        split.label,
243→        topicSubject,
244→        cachedContentName,
245→        topicList,
246→      );
247→
248→      results.push({
249→        label: split.label,
250→        questionNumber: split.questionNumber,
251→        topicTags,
252→      });
253→
254→      console.log(
255→        `  🏷️  ${split.label}: ${topicTags.length}件のタグを付与`,
256→      );
257→    }
258→
259→    return results;
260→  } finally {
261→    // キャッシュの削除（エラー時にも必ず実行）
262→    if (cachedContentName) {
263→      try {
264→        await deleteTopicContextCache(cachedContentName);
265→        console.log("  📦 Context Cache削除完了");
266→      } catch (err) {
267→        console.warn(
268→          `  ⚠ Context Cache削除に失敗: ${err instanceof Error ? err.message : err}`,
269→        );
270→      }
271→    }
272→  }
273→}
274→

