203→  if (jsonMatch) {
204→    try {
205→      return JSON.parse(jsonMatch[1]);
206→    } catch { /* fall through */ }
207→  }
208→
209→  throw new Error(
210→    `Failed to extract JSON from Gemini response: ${raw.slice(0, 300)}`,
211→  );
212→}
