216→ * 429 (Rate Limit) や 5xx エラー時に指数バックオフでリトライする
217→ */
218→export async function callWithRetry<T>(
219→  fn: () => Promise<T>,
220→  maxRetries = 3,
221→): Promise<T> {
222→  let lastError: unknown;
223→  for (let attempt = 0; attempt <= maxRetries; attempt++) {
224→    try {
225→      return await fn();
226→    } catch (err) {
227→      lastError = err;
228→      if (attempt === maxRetries) break;
229→
230→      const status = (err as { status?: number }).status;
231→      const isRetryable =
232→        status === 429 || (status !== undefined && status >= 500);
233→
234→      if (!isRetryable) throw err;
235→
236→      const delay = Math.min(1000 * 2 ** attempt, 16000);
237→      console.warn(
238→        `  ⚠ Gemini API error (status=${status}), retrying in ${delay}ms (${attempt + 1}/${maxRetries})...`,
239→      );
240→      await new Promise((r) => setTimeout(r, delay));
241→    }
242→  }
243→  throw lastError;
244→}
