  chemistry: "化学",
  biology: "生物",
  english: "英語",
  japanese: "国語",
};


/**
 * 教科別の核心 vs 補助の判定ルール
 */
const SUBJECT_RULES: Record<string, string> = {
  "数学": `■ 核心 vs 補助の区別（数学）
○ 核心 = その大問固有のテーマ。これがなければ別の問題になる
  例: 内積、垂直条件、一直線上の点、数学的帰納法、接線の方程式、放物線と接線で囲まれた面積
× 補助 = 多くの問題で汎用的に使う計算道具。なくても問題の個性は変わらない
  例: 解の公式、因数分解、判別式Dの利用、定積分計算、2次方程式の解法、Σの計算公式
判断:「この問題は何の問題？」と聞かれて答えに含まれるか？→ 含まれなければ補助`,

  "物理": `■ 核心 vs 補助の区別（物理）
