/**
 * トピック付けプロンプト改善の検証スクリプト
 *
 * 既にR2からダウンロード済みの切り出し画像に対して
 * 改善後のプロンプトでタグ付けを実行し、結果を比較する。
 *
 * Usage:
 *   ./scripts/with-env.sh npx tsx scripts/test-tag-prompt.ts --dir /tmp/osaka-bunkei-verify --subject 数学
 */

import fs from "node:fs/promises";
import path from "node:path";
import { tagSingleQuestion, normalizeTopicSubject } from "../src/phases/tag.js";
import { getTopicsForSubject } from "../src/constants/topic-master.js";

const args = process.argv.slice(2);
function getArg(name: string): string | undefined {
  const idx = args.indexOf(`--${name}`);
  return idx !== -1 ? args[idx + 1] : undefined;
}

const dir = getArg("dir");
const subject = getArg("subject");

if (!dir || !subject) {
  console.error("Usage: --dir <path-to-png-dir> --subject <subject>");
  process.exit(1);
}

const topicSubject = normalizeTopicSubject(subject);
const topicList = getTopicsForSubject(topicSubject);

if (topicList.length === 0) {
  console.error(`No topics found for subject: ${subject} (normalized: ${topicSubject})`);
  process.exit(1);
}

console.log(`Subject: ${topicSubject} (${topicList.length} topics)`);
console.log(`Dir: ${dir}\n`);

// PNGファイルを探す
const files = (await fs.readdir(dir)).filter(f => f.endsWith(".png")).sort();

for (const file of files) {
  const imagePath = path.join(dir, file);
  const imagePng = Buffer.from(await fs.readFile(imagePath));

  // ファイル名からラベルを抽出 (例: osaka_2025_math_bunkei_zenki_q1.png → "1")
  const labelMatch = file.match(/q(\d+)\.png$/);
  const label = labelMatch ? labelMatch[1] : file;

  console.log(`--- Q${label} (${file}) ---`);

  // キャッシュなしで実行（テスト用）
  const tags = await tagSingleQuestion(imagePng, label, topicSubject, undefined, topicList);

  console.log(`  Tags: ${JSON.stringify(tags, null, 2)}`);
  console.log();
}

console.log("Done.");

