 * @param subject 科目名（例: "化学", "化学(医)", "物理(医)"）
 * @returns ベース教科名、該当なしの場合はnull
 */
export function getBaseSubject(subject: string): string | null {
  // 科目名のプレフィックスでマッチング
  // 例: 「化学」「化学(医)」「化学基礎」→ 「化学」
  for (const { prefix, baseSubject } of SUBJECT_PREFIXES) {
    if (subject.startsWith(prefix)) {
      return baseSubject;
    }
  }

  // 完全一致でのフォールバック（SUPPORTED_SUBJECTSにある場合）
  if (SUPPORTED_SUBJECTS.includes(subject)) {
    return subject;
  }

  return null;
}

/**
 * 小論文の科目名から分野を抽出
 * 「小論文(理系)」→ 「理系」、「小論文(看護)」→ 「看護」など
 * @param subject 科目名
 * @returns 分野名、該当なしの場合はnull
 */
function getEssayField(subject: string): string | null {
  const match = subject.match(/^小論文\((.+)\)$/);
  return match ? match[1] : null;
}

/**
 * 面接の科目名から分野を抽出
 * 「面接(医学部)」→ 「医学部」、「面接(教育)」→ 「教育」など
 * @param subject 科目名
 * @returns 分野名、該当なしの場合はnull
 */
function getInterviewField(subject: string): string | null {
  const match = subject.match(/^面接\((.+)\)$/);
  return match ? match[1] : null;
}

/**
 * 総合問題の科目名から理系/文系を判定
 * 「総合問題(生命環境)」「総合問題(理工)」など → 「理系」
 * 「総合問題(社会)」「総合問題(人文)」など → 「文系」
 * @param subject 科目名
 * @returns 「理系」または「文系」、総合問題でない場合はnull
 * @deprecated 5階層構造への移行に伴い、getComprehensiveIsScience を使用してください
 */
function getComprehensiveField(subject: string): string | null {
  const match = subject.match(/^総合問題\((.+)\)$/);
  if (!match) return null;

  const fieldName = match[1];
  // 理系っぽいキーワード
  const scienceKeywords = ['理', '工', '生命', '環境', '情報', '医', '薬', '農', '数'];
  // 文系っぽいキーワード
  const humanitiesKeywords = ['社会', '人文', '文', '法', '経済', '経営', '国際', '教育', '観光'];

  // 理系キーワードを含むか
  if (scienceKeywords.some(kw => fieldName.includes(kw))) {
    return '理系';
  }
  // 文系キーワードを含むか
  if (humanitiesKeywords.some(kw => fieldName.includes(kw))) {
    return '文系';
  }
  // デフォルトは理系
  return '理系';
}

/**
 * 総合問題の科目名から理系かどうかを判定
 * @param subject 科目名（例: "総合問題", "総合問題(理系)", "総合問題(生命環境)"）
 * @returns 理系の場合true、文系の場合false
 */
function getComprehensiveIsScience(subject: string): boolean {
  const match = subject.match(/^総合問題\((.+)\)$/);
  if (!match) {
    // 括弧なしの「総合問題」はデフォルトで理系
    return true;
  }

  const fieldName = match[1];
  // 理系っぽいキーワード
  const scienceKeywords = ['理', '工', '生命', '環境', '情報', '医', '薬', '農', '数'];
  // 文系っぽいキーワード
  const humanitiesKeywords = ['社会', '人文', '文', '法', '経済', '経営', '国際', '教育', '観光'];

  // 文系キーワードを含むか（先に判定）
  if (humanitiesKeywords.some(kw => fieldName.includes(kw))) {
    return false;
  }
  // 理系キーワードを含むか
  if (scienceKeywords.some(kw => fieldName.includes(kw))) {
    return true;
  }
  // デフォルトは理系
  // NOTE: 未知の分野が追加された際に意図しない分類を防ぐため、開発環境でのみ警告を出す
  if (process.env.NODE_ENV === 'development') {
    console.warn(`[getComprehensiveIsScience] Unknown field "${fieldName}" defaulted to science. Consider adding it to keyword lists.`);
  }
  return true;
}

/**
 * 科目情報（ターゲット教科名、トピックリスト、理系/文系判定）
 */
export interface SubjectInfo {
  /** プロンプトに表示する教科名 */
  targetSubject: string;
  /** フィルタリング済みトピックリスト */
  topicPaths: string[];
  /** 理系科目かどうか */
  isScience: boolean;
}

// 理系科目リスト
const SCIENCE_BASE_SUBJECTS = ['数学', '物理', '化学', '生物'];

/**
 * 科目名から教科情報を取得
 * targetSubject と topicPaths の整合性を保証する
 * @param subject 科目名（例: "化学", "化学(医)", "小論文(理系)", "総合問題(生命環境)"）
 * @returns 教科情報
 */
export function getSubjectInfo(subject: string): SubjectInfo {
  // 小論文の場合
  const essayField = getEssayField(subject);
  if (essayField) {
    // 理系判定: 理系、農、生命、医療系は理系として扱う
    const scienceEssayFields = ['理系', '農', '生命', '医療'];
    const isScience = scienceEssayFields.some(f => essayField.includes(f));
    // プロンプトインジェクション対策: 改行文字をサニタイズ
    const sanitizedField = essayField.replace(/[\r\n]/g, ' ');
    return {
      targetSubject: `小論文(${sanitizedField})`,
      topicPaths: getTopicFullPathsByField('小論文', essayField),
      isScience,
    };
  }

  // 面接の場合
  const interviewField = getInterviewField(subject);
  if (interviewField) {
    // 面接は理系・文系の区別なし
    // プロンプトインジェクション対策: ホワイトリスト検証
    const isValidField = Object.prototype.hasOwnProperty.call(INTERVIEW_FIELD_MAPPING, interviewField);
    const displayField = isValidField ? interviewField : 'その他';
    return {
      targetSubject: `面接(${displayField})`,
      topicPaths: getTopicFullPathsByField('面接', interviewField),
      isScience: false,
    };
  }

  // 総合問題の場合（5階層構造対応）
  if (subject === '総合問題' || subject.startsWith('総合問題(')) {
    // 理系/文系の判定（従来の互換性のため）
    const isScience = getComprehensiveIsScience(subject);
    return {
      targetSubject: '総合問題',
      topicPaths: getTopicFullPaths('総合問題'),
      isScience,
    };
  }

  // 通常科目の場合
  const baseSubject = getBaseSubject(subject);
  if (baseSubject) {
    return {
      targetSubject: baseSubject,
      topicPaths: getTopicFullPaths(baseSubject),
      isScience: SCIENCE_BASE_SUBJECTS.includes(baseSubject),
    };
  }

  // 未知の科目の場合はデフォルト（数学）
  return {
    targetSubject: '数学',
    topicPaths: getTopicFullPaths('数学'),
    isScience: true,
  };
}

/**
 * 科目名に対応するトピックリストをフィルタリングして返す
 * @param subject 科目名（例: "化学", "化学(医)", "小論文(理系)", "総合問題(生命環境)"）
 * @returns フィルタリング済みのフルパス形式トピック配列
 * @deprecated getSubjectInfo を使用してください
 */
export function getFilteredTopicsBySubject(subject: string): string[] {
  // 小論文の場合は分野でフィルタリング
  const essayField = getEssayField(subject);
  if (essayField) {
    return getTopicFullPathsByField('小論文', essayField);
  }

  // 面接の場合は分野でフィルタリング
  const interviewField = getInterviewField(subject);
  if (interviewField) {
    return getTopicFullPathsByField('面接', interviewField);
  }

  // 総合問題の場合（5階層構造対応）
  if (subject === '総合問題' || subject.startsWith('総合問題(')) {
    return getTopicFullPaths('総合問題');
  }

  const baseSubject = getBaseSubject(subject);

  if (baseSubject) {
    // ベース教科が判定できた場合、その教科のトピックのみを返す
    return getTopicFullPaths(baseSubject);
  }

  // 該当しない場合は全トピックを返す
  return getAllTopicFullPaths();
}

/**
 * フィールドマッピングを使用して5階層トピックパスを生成する共通ヘルパー関数
 * @param subject 教科名（例: "小論文", "面接"）
 * @param field 分野名（例: "理系", "医学部"）
 * @param subjectData TOPIC_MASTERから取得した教科データ
 * @param fieldMapping フィールドマッピング
 * @param defaultFields デフォルトフィールド
 * @returns フルパス形式のトピック配列
 */
function buildFiveLayerPathsWithMapping(
  subject: string,
  field: string,
  subjectData: Record<string, Record<string, TopicValue>>,
  fieldMapping: Record<string, string[]>,
  defaultFields: string[]
): string[] {
  const paths: string[] = [];

  // フィールドマッピングから対象分野を取得（プロトタイプ汚染対策）
  const targetFields = Object.prototype.hasOwnProperty.call(fieldMapping, field)
    ? fieldMapping[field]
    : defaultFields;

  for (const targetField of targetFields) {
    const fieldData = subjectData[targetField];
    if (!fieldData) continue;

    for (const [unit, subUnits] of Object.entries(fieldData)) {
      if (typeof subUnits === 'object' && !Array.isArray(subUnits)) {
        // 5階層: 科目/分野/単元/サブ単元/トピック
        for (const [subUnit, topics] of Object.entries(subUnits as Record<string, string[]>)) {
          for (const topic of topics) {
            paths.push(`${subject}/${targetField}/${unit}/${subUnit}/${topic}`);
          }
        }
      }
    }
  }
  return paths;
}

/**
 * 特定の教科・分野のトピックリストを取得
 * @param subject 教科名（例: "小論文", "総合問題"）
 * @param field 分野名（例: "理系", "看護", "社会系"）
 * @returns フルパス形式のトピック配列
 */
function getTopicFullPathsByField(subject: string, field: string): string[] {
  const subjectData = TOPIC_MASTER[subject];
  if (!subjectData) {
    return [];
  }

  // 小論文の場合は5階層構造でフィールドマッピングを使用
  if (subject === '小論文') {
    return buildFiveLayerPathsWithMapping(
      subject, field, subjectData, ESSAY_FIELD_MAPPING, DEFAULT_ESSAY_FIELDS
    );
  }

  // 面接の場合は5階層構造でフィールドマッピングを使用
  if (subject === '面接') {
    return buildFiveLayerPathsWithMapping(
      subject, field, subjectData, INTERVIEW_FIELD_MAPPING, DEFAULT_INTERVIEW_FIELDS
    );
  }

  // 総合問題などは3階層構造
  if (!subjectData[field]) {
    return [];
  }

  const paths: string[] = [];
  const units = subjectData[field];

  for (const [unit, topics] of Object.entries(units)) {
    // 「科目/分野/トピック」の3階層、topicsはstring[]
    for (const topic of topics as string[]) {
      paths.push(`${subject}/${field}/${topic}`);
    }
  }

  return paths;
}

// 3階層パスを使用する科目（科目/分野/トピック）
const THREE_LEVEL_SUBJECTS: string[] = [];

// 5階層パスを使用する科目（科目/分野/単元/サブ単元/トピック）
const FIVE_LEVEL_SUBJECTS = ['物理', '数学', '化学', '生物', '英語', '情報', '国語', '小論文', '総合問題', '面接'];

/**
 * 科目名からフルパス形式のトピックリストを生成
 * @param subject 科目名
 * @returns フルパス形式のトピック配列
 *          5階層科目（物理・数学・化学・生物・英語・国語）: ["数学/数学Ⅱ/図形と方程式/軌跡と領域/軌跡の方程式", ...]
 *          通常科目: ["日本史/原始・古代/原始・古代/日本文化のあけぼの", ...]（4階層）
 *          小論文/総合問題: ["小論文/理系/科学技術論", ...]（3階層）
 */
export function getTopicFullPaths(subject: string): string[] {
  const subjectData = TOPIC_MASTER[subject];
  if (!subjectData) {
    return [];
  }

  const paths: string[] = [];
  const isThreeLevel = THREE_LEVEL_SUBJECTS.includes(subject);
  const isFiveLevel = FIVE_LEVEL_SUBJECTS.includes(subject);

  for (const [field, units] of Object.entries(subjectData)) {
    for (const [unit, topicsOrDetails] of Object.entries(units)) {
      if (isThreeLevel) {
        // 小論文・総合問題は「科目/分野/トピック」の3階層
        if (Array.isArray(topicsOrDetails)) {
          for (const topic of topicsOrDetails) {
            paths.push(`${subject}/${field}/${topic}`);
          }
        }
      } else if (isFiveLevel && typeof topicsOrDetails === 'object' && !Array.isArray(topicsOrDetails)) {
        // 5階層科目（物理・数学・化学・生物・英語）は「科目/分野/単元/サブ単元/トピック」
        for (const [subUnit, topics] of Object.entries(topicsOrDetails as Record<string, string[]>)) {
          for (const topic of topics) {
            paths.push(`${subject}/${field}/${unit}/${subUnit}/${topic}`);
          }
        }
      } else if (Array.isArray(topicsOrDetails)) {
        // 通常科目は「科目/分野/単元/トピック」の4階層
        for (const topic of topicsOrDetails) {
          paths.push(`${subject}/${field}/${unit}/${topic}`);
        }
      }
    }
  }

  return paths;
}

/**
 * 全科目のフルパス形式トピックリストを取得
 * @returns 全トピックのフルパス配列
 */
export function getAllTopicFullPaths(): string[] {
  const allPaths: string[] = [];

  for (const subject of SUPPORTED_SUBJECTS) {
    allPaths.push(...getTopicFullPaths(subject));
  }

  return allPaths;
}

