content.content:
  1→/**
  2→ * トピック階層類似度スコアリングエンジン
  3→ *
  4→ * 5階層フルパス形式のトピックタグ同士を比較し、類似度を算出する。
  5→ * 階層: 科目 / 分野 / 単元 / サブ単元 / トピック
  6→ * 例:   物理 / 力と運動 / 仕事とエネルギー / エネルギー保存 / 力学的エネルギー保存則
  7→ */
  8→
  9→// 階層ごとの重み（深い階層ほど指数的に重要）
 10→const LEVEL_WEIGHTS = [1, 2, 8, 24, 48];
 11→const MAX_PAIR_SCORE = LEVEL_WEIGHTS.reduce((a, b) => a + b, 0); // 83
 12→
 13→// 単元レベル(レベル3)以上の一致のみ採用
 14→const MATCH_THRESHOLD = 0.10;
 15→
 16→// 総合スコアの重み（型 vs 中身）
 17→const W_STRUCTURE = 0.65;
 18→const W_DETAIL = 0.35;
 19→
 20→// ---------- トピックペア間の類似度 ----------
 21→
 22→/**
 23→ * 2つのトピックパスの階層一致度スコアを計算する。
 24→ * 上位階層が不一致ならそれ以下は見ない。
 25→ * @returns 0.0〜1.0
 26→ */
 27→export function topicPairSimilarity(pathA: string, pathB: string): number {
 28→  const a = pathA.split('/');
 29→  const b = pathB.split('/');
 30→  let score = 0;
 31→  for (let i = 0; i < Math.min(a.length, b.length, LEVEL_WEIGHTS.length); i++) {
 32→    if (a[i] === b[i]) {
 33→      score += LEVEL_WEIGHTS[i];
 34→    } else {
 35→      break;
 36→    }
 37→  }
 38→  return score / MAX_PAIR_SCORE;
 39→}
 40→
 41→// ---------- 問題間の類似度（集合 対 集合） ----------
 42→
 43→export interface TopicMatch {
 44→  query: string;
 45→  question: string;
 46→  pairScore: number;
 47→}
 48→
 49→export interface QuestionSimilarityResult {
 50→  score: number;
 51→  matchCount: number;
 52→  matches: TopicMatch[];
 53→  // 「大問の型」(L3単元セット) と「中身」(L4/L5) の内訳
 54→  structureScore?: number;
 55→  detailScore?: number;
 56→  unitIntersection?: number;
 57→  unitQueryCount?: number;
 58→  unitDocCount?: number;
 59→  unitL4Intersection?: number;
 60→  unitL4QueryCount?: number;
 61→  unitL4DocCount?: number;
 62→}
 63→
 64→/**
 65→ * 検索クエリのトピック集合と、DB上の問題のトピック集合を比較する。
 66→ * 貪欲マッチングで1対1対応を確立し、総合スコアを算出する。
 67→ */
 68→export function questionSimilarity(
 69→  queryTopics: string[],
 70→  questionTopics: string[],
 71→): QuestionSimilarityResult {
 72→  if (queryTopics.length === 0 || questionTopics.length === 0) {
 73→    return {
 74→      score: 0,
 75→      matchCount: 0,
 76→      matches: [],
 77→      structureScore: 0,
 78→      detailScore: 0,
 79→      unitIntersection: 0,
 80→      unitQueryCount: 0,
 81→      unitDocCount: 0,
 82→      unitL4Intersection: 0,
 83→      unitL4QueryCount: 0,
 84→      unitL4DocCount: 0,
 85→    };
 86→  }
 87→
 88→  // 0) 大問の型: 単元(L3)セットの一致度
 89→  const queryUnits = extractLevel3Prefixes(queryTopics);
 90→  const docUnits = extractLevel3Prefixes(questionTopics);
 91→  const queryL4Units = extractLevel4Prefixes(queryTopics);
 92→  const docL4Units = extractLevel4Prefixes(questionTopics);
 93→
 94→  const queryUnitSet = new Set(queryUnits);
 95→  let inter = 0;
 96→  for (const unit of docUnits) {
 97→    if (queryUnitSet.has(unit)) inter++;
 98→  }
 99→
100→  if (inter === 0) {
101→    return {
102→      score: 0,
103→      matchCount: 0,
104→      matches: [],
105→      structureScore: 0,
106→      detailScore: 0,
107→      unitIntersection: 0,
108→      unitQueryCount: queryUnits.length,
109→      unitDocCount: docUnits.length,
110→      unitL4Intersection: 0,
111→      unitL4QueryCount: queryL4Units.length,
112→      unitL4DocCount: docL4Units.length,
113→    };
114→  }
115→
116→  // L3 Jaccard（単元レベル）
117→  const unionL3 = queryUnits.length + docUnits.length - inter;
118→  const jaccardL3 = inter / unionL3;
119→
120→  // L4 Jaccard（サブ単元レベル）
121→  const queryL4Set = new Set(queryL4Units);
122→  let interL4 = 0;
123→  for (const unit of docL4Units) {
124→    if (queryL4Set.has(unit)) interL4++;
125→  }
126→  const unionL4 = queryL4Units.length + docL4Units.length - interL4;
127→  const jaccardL4 = unionL4 === 0 ? 0 : interL4 / unionL4;
128→
129→  // 幾何平均で合体（L3だけ・L4だけに偏らない）
130→  const structureScore = Math.sqrt(jaccardL3 * jaccardL4);
131→
132→  // 全ペアのスコアを計算
133→  const pairs: { qi: number; di: number; score: number }[] = [];
134→  for (let qi = 0; qi < queryTopics.length; qi++) {
135→    for (let di = 0; di < questionTopics.length; di++) {
136→      const s = topicPairSimilarity(queryTopics[qi], questionTopics[di]);
137→      if (s >= MATCH_THRESHOLD) {
138→        pairs.push({ qi, di, score: s });
139→      }
140→    }
141→  }
142→
143→  // スコア降順でソート
144→  pairs.sort((a, b) => b.score - a.score);
145→
146→  // 貪欲マッチング（1対1）
147→  const usedQ = new Set<number>();
148→  const usedD = new Set<number>();
149→  const matches: TopicMatch[] = [];
150→
151→  for (const p of pairs) {
152→    if (usedQ.has(p.qi) || usedD.has(p.di)) continue;
153→    usedQ.add(p.qi);
154→    usedD.add(p.di);
155→    matches.push({
156→      query: queryTopics[p.qi],
157→      question: questionTopics[p.di],
158→      pairScore: p.score,
159→    });
160→  }
161→
162→  if (matches.length === 0) {
163→    return {
164→      score: 0,
165→      matchCount: 0,
166→      matches: [],
167→      structureScore,
168→      detailScore: 0,
169→      unitIntersection: inter,
170→      unitQueryCount: queryUnits.length,
171→      unitDocCount: docUnits.length,
172→      unitL4Intersection: interL4,
173→      unitL4QueryCount: queryL4Units.length,
174→      unitL4DocCount: docL4Units.length,
175→    };
176→  }
177→
178→  // 総合スコア計算
179→  const avgMatchQuality =
180→    matches.reduce((sum, m) => sum + m.pairScore, 0) / matches.length;
181→
182→  const minSize = Math.min(queryTopics.length, questionTopics.length);
183→  const maxSize = Math.max(queryTopics.length, questionTopics.length);
184→  const coverageSmall = matches.length / minSize;
185→  const coverageLarge = matches.length / maxSize;
186→  const coverageGeo = Math.sqrt(coverageSmall * coverageLarge);
187→  const sizeRatio = Math.sqrt(minSize / maxSize);
188→
189→  const detailScore = avgMatchQuality * coverageGeo * sizeRatio;
190→
191→  // 型(単元セット)をやや重視しつつ、中身一致も効かせる
192→  const totalScore = W_STRUCTURE * structureScore + W_DETAIL * detailScore;
193→
194→  return {
195→    score: totalScore,
196→    matchCount: matches.length,
197→    matches,
198→    structureScore,
199→    detailScore,
200→    unitIntersection: inter,
201→    unitQueryCount: queryUnits.length,
202→    unitDocCount: docUnits.length,
203→    unitL4Intersection: interL4,
204→    unitL4QueryCount: queryL4Units.length,
205→    unitL4DocCount: docL4Units.length,
206→  };
207→}
208→
209→// ---------- 星ランク変換 ----------
210→
211→export interface StarRank {
212→  stars: number; // 0〜5
213→  label: string;
214→}
215→
216→export function toStarRank(rawScore: number): StarRank {
217→  // Ver.3: 構成一致を加味するため、しきい値を引き上げ
218→  if (rawScore >= 0.72) return { stars: 5, label: '極めて類似' };
219→  if (rawScore >= 0.56) return { stars: 4, label: 'かなり類似' };
220→  if (rawScore >= 0.38) return { stars: 3, label: 'やや類似' };
221→  if (rawScore >= 0.18) return { stars: 2, label: '少し関連' };
222→  if (rawScore > 0) return { stars: 1, label: 'わずかに関連' };
223→  return { stars: 0, label: '無関係' };
224→}
225→
226→// ---------- ユーティリティ ----------
227→
228→/**
229→ * トピックパスからレベル3（単元レベル）のプレフィックスを抽出する。
230→ * 例: "物理/力と運動/運動量とその保存/運動量の保存/2物体の衝突"
231→ *   → "物理/力と運動/運動量とその保存"
232→ */
233→export function extractLevel3Prefix(topicPath: string): string {
234→  const parts = topicPath.split('/');
235→  return parts.slice(0, 3).join('/');
236→}
237→
238→/**
239→ * トピックパス配列から重複のないレベル3プレフィックスの集合を返す。
240→ */
241→export function extractLevel3Prefixes(topicPaths: string[]): string[] {
242→  const set = new Set<string>();
243→  for (const p of topicPaths) {
244→    set.add(extractLevel3Prefix(p));
245→  }
246→  return [...set];
247→}
