249→/**
250→ * トピックパスからレベル4（サブ単元レベル）のプレフィックスを抽出する。
251→ * 例: "物理/力と運動/力と運動/運動の法則/斜面上の物体"
252→ *   → "物理/力と運動/力と運動/運動の法則"
253→ */
254→export function extractLevel4Prefix(topicPath: string): string {
255→  const parts = topicPath.split('/');
256→  return parts.slice(0, 4).join('/');
257→}
258→
259→/**
260→ * トピックパス配列から重複のないレベル4プレフィックスの集合を返す。
261→ */
262→export function extractLevel4Prefixes(topicPaths: string[]): string[] {
263→  const set = new Set<string>();
264→  for (const p of topicPaths) {
265→    set.add(extractLevel4Prefix(p));
266→  }
267→  return [...set];
268→}
