 26→import { createClient, SupabaseClient } from '@supabase/supabase-js';
 27→import type { SolutionApproach } from '../types/database';
 28→
 29→interface QuestionRow {
 30→  id: string;
 31→  topic_tags: string[] | null;
 32→  solution_approaches: SolutionApproach[] | null;
 33→  document: {
 34→    subject: string;
 35→    year: number;
 36→    university: {
 37→      name: string;
 38→    };
 39→  };
 40→  question_label: string | null;
 41→}
 42→
 43→interface CliArgs {
 44→  limit?: number;
 45→  subject?: string;
 46→  university?: string;
 47→  dryRun: boolean;
 48→}
 49→
 50→function parseArgs(): CliArgs {
 51→  const args: CliArgs = { dryRun: false };
 52→  const argv = process.argv.slice(2);
 53→
 54→  for (let i = 0; i < argv.length; i++) {
 55→    if (argv[i] === '--limit' && argv[i + 1]) {
 56→      const limitVal = parseInt(argv[i + 1], 10);
 57→      if (isNaN(limitVal)) {
 58→        console.error(`❌ --limit の値が不正です: "${argv[i + 1]}" (数値を指定してください)`);
 59→        process.exit(1);
 60→      }
 61→      args.limit = limitVal;
 62→      i++;
 63→    } else if (argv[i] === '--subject' && argv[i + 1]) {
 64→      args.subject = argv[i + 1];
 65→      i++;
 66→    } else if (argv[i] === '--university' && argv[i + 1]) {
 67→      args.university = argv[i + 1];
 68→      i++;
 69→    } else if (argv[i] === '--dry-run') {
 70→      args.dryRun = true;
 71→    }
 72→  }
 73→
 74→  return args;
 75→}
