 77→function getSupabaseClient(): SupabaseClient {
 78→  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
 79→  const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
 80→
 81→  if (!supabaseUrl || !supabaseServiceKey) {
 82→    console.error('❌ Supabase環境変数が設定されていません');
 83→    console.error('   NEXT_PUBLIC_SUPABASE_URL:', supabaseUrl ? '✓' : '✗');
 84→    console.error('   SUPABASE_SERVICE_ROLE_KEY:', supabaseServiceKey ? '✓' : '✗');
 85→    process.exit(1);
 86→  }
 87→
 88→  return createClient(supabaseUrl, supabaseServiceKey, {
 89→    db: { schema: 'public' },
 90→  });
 91→}
