 93→async function fetchTargetQuestions(
 94→  supabase: SupabaseClient,
 95→  args: CliArgs
 96→): Promise<QuestionRow[]> {
 97→  let query = supabase
 98→    .from('kakomon_questions')
 99→    .select(`
100→      id,
101→      topic_tags,
102→      solution_approaches,
103→      question_label,
104→      document:kakomon_documents!inner(
105→        subject,
106→        year,
107→        university:kakomon_universities!inner(name)
108→      )
109→    `)
110→    .not('topic_tags', 'eq', '{}');
111→
112→  if (args.university) {
113→    query = query.eq('kakomon_documents.kakomon_universities.name', args.university);
114→  }
115→
116→  if (args.subject) {
117→    // 前方一致検索: "物理" → "物理", "物理(医)" 両方にマッチ
118→    query = query.like('kakomon_documents.subject', `${args.subject}%`);
119→  }
120→
121→  query = query.order('created_at', { ascending: true });
122→
123→  if (args.limit) {
124→    query = query.limit(args.limit);
125→  }
126→
127→  const { data, error } = await query;
128→
129→  if (error) {
130→    console.error('❌ 問題取得エラー:', error.message);
131→    process.exit(1);
132→  }
133→
134→  return (data || []) as unknown as QuestionRow[];
135→}
