137→interface RevalidationResult {
138→  questionId: string;
139→  label: string;
140→  originalTagCount: number;
141→  validTagCount: number;
142→  rejectedTags: string[];
143→}
144→
145→function revalidateQuestion(
146→  question: QuestionRow,
147→  topicPathSet: Set<string>
148→): RevalidationResult {
149→  const doc = question.document;
150→  const universityName = doc?.university?.name || 'Unknown';
151→  const label = `${universityName} ${doc?.year}年 ${doc?.subject} ${question.question_label || ''}`;
152→
153→  const originalTags = question.topic_tags || [];
154→  const validTags = originalTags.filter(t => topicPathSet.has(t));
155→  const rejectedTags = originalTags.filter(t => !topicPathSet.has(t));
156→
157→  return {
158→    questionId: question.id,
159→    label,
160→    originalTagCount: originalTags.length,
161→    validTagCount: validTags.length,
162→    rejectedTags,
163→  };
164→}
165→
166→function buildUpdatedData(
167→  question: QuestionRow,
168→  topicPathSet: Set<string>
169→): { topic_tags: string[] } {
170→  const validTags = (question.topic_tags || []).filter(t => topicPathSet.has(t));
171→
172→  return {
173→    topic_tags: validTags,
174→  };
175→}
176→
177→async function main() {
178→  console.log('🔍 topic_tags 再バリデーション一括処理を開始します\n');
179→
180→  const args = parseArgs();
181→  const supabase = getSupabaseClient();
182→
183→  // topic-masterを動的インポート
184→  const { getSubjectInfo } = await import('../lib/constants/topic-master');
185→
186→  console.log('📋 オプション:');
187→  console.log(`   --limit: ${args.limit ?? '制限なし'}`);
188→  console.log(`   --subject: ${args.subject ? `${args.subject}% (前方一致)` : '全教科'}`);
189→  console.log(`   --university: ${args.university ?? '全大学'}`);
190→  console.log(`   --dry-run: ${args.dryRun ? 'ON（変更を適用しません）' : 'OFF'}`);
191→
192→  // 対象問題取得
193→  const questions = await fetchTargetQuestions(supabase, args);
194→
195→  if (questions.length === 0) {
196→    console.log('\n✨ 処理対象の問題がありません');
197→    process.exit(0);
198→  }
199→
200→  console.log(`\n📚 対象問題: ${questions.length}件\n`);
201→
202→  // 科目ごとのtopicPathsをSetでキャッシュ（各科目1回のみSet生成）
203→  const topicPathSetCache: Record<string, Set<string>> = {};
204→
205→  let totalQuestions = 0;
206→  let modifiedCount = 0;
207→  let totalRejected = 0;
208→  let failCount = 0;
209→  const allRejectedTags: Record<string, number> = {};
210→
211→  for (let i = 0; i < questions.length; i++) {
212→    const question = questions[i];
213→    const subject = question.document?.subject || '数学';
214→
215→    // topicPathSetをキャッシュから取得（or 計算してキャッシュ）
216→    if (!topicPathSetCache[subject]) {
217→      const info = getSubjectInfo(subject);
218→      topicPathSetCache[subject] = new Set(info.topicPaths);
219→    }
220→    const topicPathSet = topicPathSetCache[subject];
221→
222→    const result = revalidateQuestion(question, topicPathSet);
223→    totalQuestions++;
224→
225→    if (result.rejectedTags.length > 0) {
226→      modifiedCount++;
227→      totalRejected += result.rejectedTags.length;
228→
229→      console.log(`[${i + 1}/${questions.length}] ${result.label}`);
230→      console.log(`   tags: ${result.originalTagCount} → ${result.validTagCount} (${result.rejectedTags.length}件除外)`);
231→      console.log(`   除外: ${result.rejectedTags.join(', ')}`);
232→
233→      // 除外されたタグの集計
234→      for (const tag of result.rejectedTags) {
235→        allRejectedTags[tag] = (allRejectedTags[tag] || 0) + 1;
236→      }
237→
238→      // DB更新
239→      if (!args.dryRun) {
240→        const updatedData = buildUpdatedData(question, topicPathSet);
241→
242→        const { error } = await supabase
243→          .from('kakomon_questions')
244→          .update({
245→            topic_tags: updatedData.topic_tags,
246→          })
247→          .eq('id', question.id);
248→
249→        if (error) {
250→          console.error(`   ❌ 更新エラー: ${error.message}`);
251→          failCount++;
252→        }
253→      }
254→    }
255→  }
256→
257→  // サマリー
258→  console.log('\n' + '='.repeat(60));
259→  console.log('📊 再バリデーション結果サマリー');
260→  console.log('='.repeat(60));
261→  console.log(`   総問題数: ${totalQuestions}件`);
262→  console.log(`   修正対象: ${modifiedCount}件`);
263→  console.log(`   除外タグ総数: ${totalRejected}件`);
264→  if (!args.dryRun) {
265→    console.log(`   更新成功: ${modifiedCount - failCount}件`);
266→    console.log(`   更新失敗: ${failCount}件`);
267→  } else {
268→    console.log(`   ⚠️  dry-runモード: 実際の更新は行っていません`);
269→  }
270→
271→  // 除外されたタグのランキング
272→  const sortedRejected = Object.entries(allRejectedTags)
273→    .sort((a, b) => b[1] - a[1]);
274→
275→  if (sortedRejected.length > 0) {
276→    console.log('\n📋 除外されたタグ（出現回数順）:');
277→    for (const [tag, count] of sortedRejected.slice(0, 20)) {
278→      console.log(`   ${count}回 - ${tag}`);
279→    }
280→    if (sortedRejected.length > 20) {
281→      console.log(`   ... 他 ${sortedRejected.length - 20}種類`);
282→    }
283→  }
284→
285→  if (failCount > 0) {
286→    process.exit(1);
287→  }
288→}
289→
290→main().catch((error) => {
291→  console.error('予期せぬエラー:', error);
292→  process.exit(1);
293→});
