157→export async function ocrPdf(pdfBuffer: Buffer): Promise<OcrPdfResult> {
158→  const client = getGeminiClient();
159→  const model = client.getGenerativeModel({ model: getVisionModel() });
160→
161→  const pdfPart: Part = {
162→    inlineData: {
163→      data: pdfBuffer.toString('base64'),
164→      mimeType: 'application/pdf',
165→    },
166→  };
167→
168→  const prompt = `この PDF は大学入試の問題です。
169→全ページのテキストを正確に文字起こししてください。
170→
171→【ルール】
172→- 数式は LaTeX 形式（$...$ または $$...$$）で記述してください
173→- 図がある場合は [図] と記載してください
174→- 表がある場合は、できる限り再現してください
175→- 箇条書きや段落の構造は維持してください
176→- 各ページの区切りには「--- ページ N ---」という形式でマーカーを入れてください（N はページ番号）
177→- 最後に「【総ページ数: X】」という形式で総ページ数を記載してください`;
178→
179→  const result = await model.generateContent([prompt, pdfPart]);
180→  const response = result.response;
181→  const text = response.text();
182→
183→  // ページ数を抽出
184→  const pageCountMatch = text.match(/【総ページ数:\s*(\d+)】/);
185→  let pageCount: number;
186→  if (pageCountMatch) {
187→    pageCount = parseInt(pageCountMatch[1], 10);
188→  } else if (!text.trim()) {
189→    // 空のテキストの場合は0ページ
190→    pageCount = 0;
191→  } else {
192→    // フォールバック: ページマーカーをカウント
193→    const pageMarkers = text.match(/---\s*ページ\s*\d+\s*---/g);
194→    pageCount = pageMarkers ? pageMarkers.length : 1;
195→  }
196→
197→  // 総ページ数マーカーを除去した本文を返す
198→  const cleanedText = text.replace(/【総ページ数:\s*\d+】\s*$/, '').trim();
199→
200→  return {
201→    text: cleanedText,
202→    pageCount,
203→  };
204→}
