313→/**
314→ * Geminiの出力を後処理し、topic_tagsをマスタリストでバリデーション
315→ * topicPathsが指定された場合、マスタリストに存在するパスのみを残す
316→ */
317→function postProcessQuestions(result: ParseQuestionsResult, topicPaths?: string[]): ParseQuestionsResult {
318→  const topicPathSet = topicPaths ? new Set(topicPaths) : undefined;
319→  let totalRaw = 0;
320→  let totalRejected = 0;
321→
322→  const processed = {
323→    questions: result.questions.map(q => {
324→      const rawTags = q.topic_tags || [];
325→
326→      if (!topicPathSet) {
327→        return { ...q, topic_tags: rawTags };
328→      }
329→
330→      const validTags = [...new Set(rawTags.filter(t => topicPathSet.has(t)))];
331→
332→      totalRaw += rawTags.length;
333→      totalRejected += rawTags.length - validTags.length;
334→
335→      return {
336→        ...q,
337→        topic_tags: validTags,
338→      };
339→    }),
340→  };
341→
342→  if (topicPathSet && totalRejected > 0) {
343→    console.warn(
344→      `[postProcessQuestions] マスタリスト照合: ${totalRejected}/${totalRaw}件のトピックパスを除外`
345→    );
346→  }
347→
348→  return processed;
349→}
