351→/**
352→ * Gemini APIレスポンスから大問境界情報をパース・整形する
353→ * @param text - Gemini APIからのレスポンステキスト
354→ * @param functionName - ログ出力用の関数名
355→ */
356→function parseBoundariesResponse(text: string, functionName: string): DetectBoundariesResult {
357→  // JSONを抽出してパース
358→  const parsed = extractAndParseJson<{
359→    questions: Array<{
360→      question_number: number;
361→      label: string;
362→      start_page: number;
363→    }>;
364→    total_pages: number;
365→  }>(text);
366→
367→  // end_page を計算: 次の大問の start_page - 1（最後の大問は null）
368→  const questionsWithEndPage: QuestionBoundary[] = parsed.questions.map((q, index) => {
369→    const nextQuestion = parsed.questions[index + 1];
370→    const end_page = nextQuestion
371→      ? nextQuestion.start_page - 1
372→      : null;
373→
374→    return {
375→      question_number: q.question_number,
376→      label: q.label,
377→      start_page: q.start_page,
378→      end_page,
379→    };
380→  });
381→
382→  // 大問が1つも検出されない場合の警告ログ
383→  if (questionsWithEndPage.length === 0) {
384→    console.warn(`⚠️ ${functionName}: 大問が1つも検出されませんでした`);
385→  }
386→
387→  return {
388→    questions: questionsWithEndPage,
389→    total_pages: parsed.total_pages,
390→  };
391→}
