401→export async function detectQuestionBoundaries(pdfBuffer: Buffer): Promise<DetectBoundariesResult> {
402→  if (!isAgenticVisionEnabled()) {
403→    return detectQuestionBoundariesFallback(pdfBuffer);
404→  }
