406→  const client = getGeminiClient();
407→
408→  // Agentic Vision: Code Executionツールを有効化
409→  // プロンプトで明示的にPythonコード実行を指示することで有効化される
410→  const tools = isCodeExecutionEnabled() ? [{ codeExecution: {} }] : undefined;
411→  const model = client.getGenerativeModel({
412→    model: getVisionModel(),
413→    tools,
414→  });
415→
416→  const pdfPart: Part = {
417→    inlineData: {
418→      data: pdfBuffer.toString('base64'),
419→      mimeType: 'application/pdf',
420→    },
421→  };
422→
423→  const prompt = `このPDFは大学入試問題です。各大問の開始位置を視覚的に検出してください。
424→
425→【重要】必ずPythonコードを生成・実行して以下を行ってください：
426→1. PDFの各ページを画像として取得
427→2. 「第○問」「問○」「[1]」「1.」などの大問開始パターンを探す
428→3. 検出した箇所にバウンディングボックス（赤い矩形）を描画
429→4. 描画結果を確認して検出が正しいか検証
