457→    // Code Executionが失敗した場合のフォールバック処理
458→    console.error('❌ detectQuestionBoundaries: Agentic Vision処理でエラーが発生しました');
459→    console.error('Error:', error instanceof Error ? error.message : error);
460→
461→    // フォールバック: Code Executionなしで再試行
462→    console.log('🔄 フォールバック: 通常のVision APIで再試行します...');
463→    return detectQuestionBoundariesFallback(pdfBuffer);
464→  }
465→}
