 12→export async function POST(request: NextRequest, { params }: RouteParams) {
 13→  if (!isSupabaseConfigured() || !supabaseAdmin) {
 14→    return NextResponse.json(
 15→      { error: 'Supabase is not configured' },
 16→      { status: 500 }
 17→    );
 18→  }
 19→
 20→  try {
 21→    const { id } = await params;
 22→
 23→    // Fetch document to validate
 24→    const { data: document, error: docError } = await supabaseAdmin
 25→      .from('kakomon_documents')
 26→      .select('id, full_text, ocr_status, subject, parse_status')
 27→      .eq('id', id)
 28→      .single();
 29→
 30→    if (docError || !document) {
 31→      return NextResponse.json(
 32→        { error: 'ドキュメントが見つかりません' },
 33→        { status: 404 }
 34→      );
 35→    }
 36→
 37→    if (document.ocr_status !== 'completed') {
 38→      return NextResponse.json(
 39→        { error: 'OCR処理が完了していません。先にOCRを実行してください。' },
 40→        { status: 400 }
 41→      );
 42→    }
 43→
 44→    if (!document.full_text) {
 45→      return NextResponse.json(
 46→        { error: 'OCRテキストがありません。再度OCRを実行してください。' },
 47→        { status: 400 }
 48→      );
 49→    }
 50→
 51→    // Check if already processing
 52→    if (document.parse_status === 'processing') {
 53→      return NextResponse.json(
 54→        { error: '大問分割処理が既に実行中です' },
 55→        { status: 409 }
 56→      );
 57→    }
 58→
 59→    // Get the base URL for the background function
 60→    const baseUrl = process.env.URL || process.env.DEPLOY_URL || '';
 61→
 62→    // If no base URL available (local dev or non-Netlify), use synchronous processing
 63→    if (!baseUrl) {
 64→      console.log('No Netlify URL available, using synchronous processing');
 65→      return await processSynchronously(id, document.full_text, document.subject);
 66→    }
 67→
 68→    // Set status to processing for background function
 69→    await supabaseAdmin
 70→      .from('kakomon_documents')
 71→      .update({ parse_status: 'processing' })
 72→      .eq('id', id);
 73→
 74→    const backgroundFunctionUrl = `${baseUrl}/.netlify/functions/parse-questions-background`;
 75→
 76→    // Trigger background function (fire and forget)
 77→    try {
 78→      fetch(backgroundFunctionUrl, {
 79→        method: 'POST',
 80→        headers: {
 81→          'Content-Type': 'application/json',
 82→        },
 83→        body: JSON.stringify({ documentId: id }),
 84→      }).catch(err => {
 85→        console.error('Failed to trigger background function:', err);
 86→      });
 87→    } catch (triggerError) {
 88→      console.error('Error triggering background function:', triggerError);
 89→    }
 90→
 91→    // Return 202 Accepted immediately
 92→    return NextResponse.json(
 93→      {
 94→        success: true,
 95→        message: '大問分割処理を開始しました。処理完了までお待ちください。',
 96→        status: 'processing',
 97→      },
 98→      { status: 202 }
 99→    );
100→
101→  } catch (error) {
102→    console.error('Parse questions error:', error);
103→    return NextResponse.json(
104→      { error: '大問分割の開始に失敗しました' },
105→      { status: 500 }
106→    );
107→  }
108→}
