110→// Synchronous processing fallback for local dev or when background function unavailable
111→async function processSynchronously(
112→  documentId: string,
113→  fullText: string,
114→  subject: string | null
115→): Promise<NextResponse> {
116→  try {
117→    // Delete existing questions
118→    await supabaseAdmin!
119→      .from('kakomon_questions')
120→      .delete()
121→      .eq('document_id', documentId);
122→
123→    // Parse questions using Gemini
124→    const result = await parseQuestions(fullText, subject || undefined);
125→
126→    if (!result.questions || result.questions.length === 0) {
127→      return NextResponse.json({
128→        success: true,
129→        message: '大問が見つかりませんでした',
130→        question_count: 0,
131→      });
132→    }
133→
134→    // Insert questions into database
135→    const questionsToInsert = result.questions.map((q) => ({
136→      document_id: documentId,
137→      question_number: q.question_number,
138→      question_label: q.question_label,
139→      sub_question_count: q.sub_question_count,
140→      topic_tags: q.topic_tags || [],
141→      subtopics: [],
142→      difficulty: null,
143→      sub_questions: null,
144→      start_page: q.start_page ?? null,
145→      end_page: q.end_page ?? null,
146→      solution_approaches: q.solution_approaches ?? [],
147→    }));
148→
149→    const { data: insertedQuestions, error: insertError } = await supabaseAdmin!
150→      .from('kakomon_questions')
151→      .insert(questionsToInsert)
152→      .select('id');
153→
154→    if (insertError) {
155→      console.error('Failed to insert questions:', insertError);
156→      return NextResponse.json(
157→        { error: '大問の保存に失敗しました' },
158→        { status: 500 }
159→      );
160→    }
161→
162→    // Update document question_count
163→    await supabaseAdmin!
164→      .from('kakomon_documents')
165→      .update({ question_count: result.questions.length })
166→      .eq('id', documentId);
167→
168→    return NextResponse.json({
169→      success: true,
170→      message: `${result.questions.length}個の大問を抽出しました`,
171→      question_count: result.questions.length,
172→      questions: insertedQuestions,
173→    });
174→
175→  } catch (error) {
176→    console.error('Synchronous parse error:', error);
177→    return NextResponse.json(
178→      { error: '大問分割中にエラーが発生しました' },
179→      { status: 500 }
180→    );
181→  }
182→}
