 15→async function assignTopicTags(content: string, subject: string): Promise<string[]> {
 16→  const client = getGeminiClient();
 17→  const visionModel = process.env.GEMINI_VISION_MODEL;
 18→  if (!visionModel) {
 19→    throw new Error('GEMINI_VISION_MODEL が設定されていません');
 20→  }
 21→  const model = client.getGenerativeModel({ model: visionModel });
 22→  const { topicPaths } = getSubjectInfo(subject);
 23→
 24→  const prompt = `以下の問題文を読み、該当するトピックタグを選んでください。
 25→
 26→## ルール
 27→- 以下の許可リストから**のみ**選択（リスト外は絶対に使わない）
 28→- 1〜5個程度選択
 29→- JSON配列のみを返す（説明文不要）
 30→
 31→## 許可されたトピックリスト
 32→${topicPaths.join('\n')}
 33→
 34→## 問題文
 35→${content}
 36→
 37→## 出力形式
 38→\`\`\`json
 39→["トピック1", "トピック2"]
 40→\`\`\``;
 41→
 42→  const result = await model.generateContent(prompt);
 43→  const text = result.response.text();
 44→  const tags = extractAndParseJson<string[]>(text);
 45→
 46→  // バリデーション
 47→  const allowedSet = new Set(topicPaths);
 48→  const validated = tags.filter(t => allowedSet.has(t));
 49→
 50→  if (validated.length === 0 && tags.length > 0) {
 51→    console.warn('  ⚠ 全タグがリスト外:', tags.slice(0, 3).join(', '));
 52→  }
 53→
 54→  return validated;
 55→}
