 57→async function main() {
 58→  const supabase = createClient(
 59→    process.env.NEXT_PUBLIC_SUPABASE_URL as string,
 60→    process.env.SUPABASE_SERVICE_ROLE_KEY as string
 61→  );
 62→
 63→  const { data: unis } = await supabase.from('kakomon_universities').select('id').like('name', '%山梨%');
 64→  if (!unis?.length) { console.error('山梨大学が見つかりません'); process.exit(1); }
 65→
 66→  const { data: docs } = await supabase.from('kakomon_documents')
 67→    .select('id, year, exam_type, subject')
 68→    .in('university_id', unis.map(u => u.id))
 69→    .eq('subject', '物理').eq('content_type', 'problem');
 70→  if (!docs?.length) { console.error('ドキュメントなし'); process.exit(1); }
 71→
 72→  const docMap = new Map(docs.map(d => [d.id, d]));
 73→
 74→  const { data: questions } = await supabase.from('kakomon_questions')
 75→    .select('id, question_number, document_id, content')
 76→    .in('document_id', docs.map(d => d.id))
 77→    .order('document_id').order('question_number');
 78→  if (!questions?.length) { console.error('大問なし'); process.exit(1); }
 79→
 80→  console.log(`=== 山梨大学 物理 トピック付与のみ ===`);
 81→  console.log(`対象: ${questions.length}問\n`);
 82→
 83→  let success = 0, failed = 0;
 84→
 85→  for (const q of questions) {
 86→    const doc = docMap.get(q.document_id);
 87→    const label = `${doc?.year} ${doc?.exam_type} Q${q.question_number}`;
 88→
 89→    if (!q.content?.trim()) { console.log(`[SKIP] ${label} - content空`); continue; }
