 95→      const { error } = await supabase.from('kakomon_questions')
 96→        .update({ topic_tags: tags })
 97→        .eq('id', q.id);
 98→
 99→      if (error) {
100→        console.log(` [NG] ${error.message}`);
101→        failed++;
102→      } else {
103→        console.log(` [OK] ${tags.length}件`);
104→        tags.forEach(t => console.log(`    ${t}`));
105→        success++;
106→      }
107→      await sleep(1500);
108→    } catch (err: unknown) {
109→      const message = err instanceof Error ? err.message : String(err);
110→      console.log(` [NG] ${message}`);
111→      failed++;
112→      if (message.includes('429')) { console.log('  30秒待機...'); await sleep(30000); }
113→      else await sleep(2000);
114→    }
115→  }
116→
117→  console.log(`\n=== 完了: 成功${success} 失敗${failed} ===`);
118→  if (failed > 0) process.exit(1);
