 43→function readBooleanEnv(name: string, defaultValue: boolean): boolean {
 44→  const value = process.env[name];
 45→  if (value === undefined) return defaultValue;
 46→  const normalized = value.trim().toLowerCase();
 47→  if (['1', 'true', 'yes', 'on'].includes(normalized)) return true;
 48→  if (['0', 'false', 'no', 'off'].includes(normalized)) return false;
 49→  return defaultValue;
 50→}
