/**
 * Gemini APIレスポンスのパース用ユーティリティ
 *
 * JSONパースに関する共通ロジックを提供
 */

/**
 * Geminiが返すJSONの不正なエスケープ文字を修正する
 * - \' → ' (JSONでは\'は無効)
 * - \α, \β などのギリシャ文字エスケープ → そのまま
 * - その他の無効なエスケープシーケンスを修正
 */
export function sanitizeJsonString(jsonStr: string): string {
  // JSONで有効なエスケープ: \", \\, \/, \b, \f, \n, \r, \t, \uXXXX
  // それ以外の \X は X に変換する

  // 文字列リテラル内のみを処理するため、一旦文字列を走査
  let result = '';
  let inString = false;
  let i = 0;

  while (i < jsonStr.length) {
    const char = jsonStr[i];

    if (char === '"') {
      // 文字列の開始/終了を検出
      // 直前の連続する\の数を数えて、エスケープされているかを判定
      let backslashCount = 0;
      let j = i - 1;
      while (j >= 0 && jsonStr[j] === '\\') {
        backslashCount++;
        j--;
      }
      if (backslashCount % 2 === 0) {
        // 偶数個のバックスラッシュ → "はエスケープされていない
        inString = !inString;
      }
      result += char;
      i++;
    } else if (inString && char === '\\' && i + 1 < jsonStr.length) {
      const nextChar = jsonStr[i + 1];

      // 有効なエスケープシーケンスかチェック
      if ('"\\bfnrt/'.includes(nextChar)) {
        // 有効なエスケープ
        result += char + nextChar;
        i += 2;
      } else if (nextChar === 'u' && i + 5 < jsonStr.length) {
        // \uXXXX 形式をチェック
        const hex = jsonStr.substring(i + 2, i + 6);
        if (/^[0-9a-fA-F]{4}$/.test(hex)) {
          result += jsonStr.substring(i, i + 6);
          i += 6;
        } else {
          // 無効な\uシーケンス → \を削除
          result += nextChar;
          i += 2;
        }
      } else if (nextChar === "'") {
        // \' → ' (JSONでは\'は無効だが、よくある誤り)
        result += "'";
        i += 2;
      } else {
        // その他の無効なエスケープ → バックスラッシュを削除して次の文字をそのまま
        result += nextChar;
        i += 2;
      }
    } else {
      result += char;
      i++;
    }
  }

  return result;
}

/**
 * JSONテキストを抽出してパースする
 * マークダウンコードブロックの処理と不正エスケープの修正を行う
 */
export function extractAndParseJson<T>(text: string): T {
  // 1. マークダウンコードブロックからJSONを抽出
  let jsonText = text;
  const jsonMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) {
    jsonText = jsonMatch[1].trim();
  }

  // 2. 不正なエスケープ文字を修正
  const sanitized = sanitizeJsonString(jsonText);

  // 3. パースを試行
  try {
    return JSON.parse(sanitized) as T;
  } catch (firstError) {
    // 4. 失敗した場合、JSONオブジェクトを直接抽出して再試行
    const objectMatch = text.match(/\{[\s\S]*\}/);
    if (objectMatch) {
      const sanitizedObject = sanitizeJsonString(objectMatch[0]);
      try {
        return JSON.parse(sanitizedObject) as T;
      } catch (secondError) {
        // デバッグ用にレスポンスをログ出力
        console.error('\n⚠️  JSONパースエラー - デバッグ情報:');
        console.error('--- 元のレスポンス (先頭1000文字) ---');
        console.error(text.substring(0, 1000));
        console.error('--- サニタイズ後 (先頭1000文字) ---');
        console.error(sanitizedObject.substring(0, 1000));
        console.error('--- エラー詳細 ---');
        console.error(
          '1回目:',
          firstError instanceof Error ? firstError.message : firstError
        );
        console.error(
          '2回目:',
          secondError instanceof Error ? secondError.message : secondError
        );
        throw secondError;
      }
    }

    // JSONオブジェクトが見つからない場合
    console.error('\n⚠️  JSONパースエラー - デバッグ情報:');
    console.error('--- 元のレスポンス (先頭1000文字) ---');
    console.error(text.substring(0, 1000));
    console.error('--- サニタイズ後 (先頭1000文字) ---');
    console.error(sanitized.substring(0, 1000));
    console.error('--- エラー詳細 ---');
    console.error(
      '1回目:',
      firstError instanceof Error ? firstError.message : firstError
    );
    throw new Error(
      'Failed to parse Gemini response as JSON: No valid JSON object found'
    );
  }
}

