export async function parseQuestions(fullText: string, subject?: string): Promise<ParseQuestionsResult> {
  const client = getGeminiClient();
  const model = client.getGenerativeModel({ model: getParseModel() });

  // 科目に応じた情報を取得（targetSubjectとtopicPathsの整合性を保証）
  const subjectInfo = getSubjectInfo(subject || '数学');
  // プロンプトインジェクション対策: JSONテンプレート内で使うためダブルクォートをエスケープ
  const targetSubject = subjectInfo.targetSubject.replace(/"/g, '\\"');
  const { topicPaths, isScience } = subjectInfo;

  // 理系/文系に応じた解法指示
  const approachInstruction = isScience
    ? '考えられる主要な解法を**全て**挙げてください'
    : '主要なアプローチを**1つ**挙げてください';

  const prompt = `あなたは大学入試問題の分析者です。

以下は大学入試問題のOCRテキストです。
大問ごとに分割し、以下のJSON形式で返してください:

{
  "questions": [
    {
      "question_number": 1,
      "question_label": "第1問",
      "content": "問題文...",
      "sub_question_count": 3,
      "topic_tags": ["${targetSubject}/分野/単元/サブ単元/トピック"],
      "solution_approaches": [
        {
          "method": "解法名",
          "steps": ["手順1", "手順2", "..."]
        }
      ],
      "start_page": 1,
      "end_page": 2
    }
  ]
}

【教科判定ルール】
- 現在の教科: ${targetSubject}（${isScience ? '理系科目' : '文系科目'}）
- ${approachInstruction}

【出力ルール】
- 大問の区切りは「第1問」「問1」「[1]」「1.」などのパターンで判断
- 小問は (1), (2), (ア), (イ) などで数える
- start_page, end_page は各大問が何ページ目から何ページ目に存在するかを示す（1始まり）
- OCRテキスト内のページ区切り情報（「--- Page X ---」「ページX」「-X-」等）からページ番号を判定してください
- ページ情報が特定できない場合は null を設定してください

【解法アプローチのルール】
- method: 解法の名称（例：「エネルギー保存則」「微分法による最大・最小」）
- steps: 解法の手順を箇条書きで記載

【トピック選択ルール - 重要】
- topic_tags: 大問全体に対するトピックタグをフルパス形式で記載（大問単位で1〜4個、最大5個）
- 以下のリストに存在するトピックのみを使用してください（リスト外のトピックは絶対に使用しないでください）：
${topicPaths.join('\n')}
- 複数選択可。必ず上記リスト内の表記をそのまま使用してください。
- 上記リストは「${targetSubject}」の教科に対応したトピックです。他の教科のトピックは存在しないため選択できません。

${TOPIC_GRANULARITY_RULES}

- JSONのみを返してください。説明文は不要です。

OCRテキスト:
${fullText}`;

  const result = await model.generateContent(prompt);
  const response = result.response;
  const text = response.text();

  // JSONを抽出・サニタイズ・パース
  const parsed = extractAndParseJson<ParseQuestionsResult>(text);
  // 後処理: topic_tagsをマスタリスト照合でフィルタ
  return postProcessQuestions(parsed, topicPaths);
}

/**
 * Geminiの出力を後処理し、topic_tagsをマスタリストでバリデーション
 * topicPathsが指定された場合、マスタリストに存在するパスのみを残す
 */
function postProcessQuestions(result: ParseQuestionsResult, topicPaths?: string[]): ParseQuestionsResult {
  const topicPathSet = topicPaths ? new Set(topicPaths) : undefined;
  let totalRaw = 0;
  let totalRejected = 0;

  const processed = {
    questions: result.questions.map(q => {
      const rawTags = q.topic_tags || [];

      if (!topicPathSet) {
        return { ...q, topic_tags: rawTags };
      }

      const validTags = [...new Set(rawTags.filter(t => topicPathSet.has(t)))];

      totalRaw += rawTags.length;
      totalRejected += rawTags.length - validTags.length;

      return {
        ...q,
        topic_tags: validTags,
      };
    }),
  };

  if (topicPathSet && totalRejected > 0) {
    console.warn(
      `[postProcessQuestions] マスタリスト照合: ${totalRejected}/${totalRaw}件のトピックパスを除外`
    );
  }

  return processed;
}

/**
 * Gemini APIレスポンスから大問境界情報をパース・整形する
 * @param text - Gemini APIからのレスポンステキスト
 * @param functionName - ログ出力用の関数名
 */
function parseBoundariesResponse(text: string, functionName: string): DetectBoundariesResult {
  // JSONを抽出してパース
  const parsed = extractAndParseJson<{
    questions: Array<{
      question_number: number;
      label: string;
      start_page: number;
    }>;
    total_pages: number;
  }>(text);

  // end_page を計算: 次の大問の start_page - 1（最後の大問は null）
  const questionsWithEndPage: QuestionBoundary[] = parsed.questions.map((q, index) => {
    const nextQuestion = parsed.questions[index + 1];
    const end_page = nextQuestion
      ? nextQuestion.start_page - 1
      : null;

    return {
      question_number: q.question_number,
      label: q.label,
      start_page: q.start_page,
      end_page,
    };
  });

  // 大問が1つも検出されない場合の警告ログ
  if (questionsWithEndPage.length === 0) {
    console.warn(`⚠️ ${functionName}: 大問が1つも検出されませんでした`);
  }

  return {
    questions: questionsWithEndPage,
    total_pages: parsed.total_pages,
  };
}

/**
 * Agentic Vision を使用してPDFから大問の境界を視覚的に検出する
 * Code Execution ツールを使用して画像分析を行う
 *
 * Note: 思考モード（thinkingConfig）は新SDK (@google/genai) で対応済み。
 * 必要に応じて getGeminiGenAIClient() を使用し、
 * config.thinkingConfig.thinkingLevel で思考レベルを設定可能。
 */
export async function detectQuestionBoundaries(pdfBuffer: Buffer): Promise<DetectBoundariesResult> {
  if (!isAgenticVisionEnabled()) {
    return detectQuestionBoundariesFallback(pdfBuffer);
  }

  const client = getGeminiClient();

  // Agentic Vision: Code Executionツールを有効化
  // プロンプトで明示的にPythonコード実行を指示することで有効化される
  const tools = isCodeExecutionEnabled() ? [{ codeExecution: {} }] : undefined;
  const model = client.getGenerativeModel({
    model: getVisionModel(),
    tools,
  });

  const pdfPart: Part = {
    inlineData: {
      data: pdfBuffer.toString('base64'),
      mimeType: 'application/pdf',
    },
  };

  const prompt = `このPDFは大学入試問題です。各大問の開始位置を視覚的に検出してください。

【重要】必ずPythonコードを生成・実行して以下を行ってください：
1. PDFの各ページを画像として取得
2. 「第○問」「問○」「[1]」「1.」などの大問開始パターンを探す
3. 検出した箇所にバウンディングボックス（赤い矩形）を描画
4. 描画結果を確認して検出が正しいか検証

【検出対象パターン】
- 「第1問」「第2問」...
- 「問1」「問2」...
- 「[1]」「[2]」...
- 「1.」「2.」...（大きなフォントで問題の区切りになっているもの）

【出力形式】
検証完了後、以下のJSON形式で返してください：
{
  "questions": [
    { "question_number": 1, "label": "第1問", "start_page": 1 },
    { "question_number": 2, "label": "第2問", "start_page": 3 }
  ],
  "total_pages": 5
}

- 大問が見つからない場合は空配列を返す
- JSONのみを返し、説明は不要`;

  try {
    const result = await model.generateContent([prompt, pdfPart]);
    const response = result.response;
    const text = response.text();

    return parseBoundariesResponse(text, 'detectQuestionBoundaries');
  } catch (error) {
    // Code Executionが失敗した場合のフォールバック処理
    console.error('❌ detectQuestionBoundaries: Agentic Vision処理でエラーが発生しました');
    console.error('Error:', error instanceof Error ? error.message : error);

    // フォールバック: Code Executionなしで再試行
    console.log('🔄 フォールバック: 通常のVision APIで再試行します...');
    return detectQuestionBoundariesFallback(pdfBuffer);
  }
}

/**
 * フォールバック: Code Executionなしで大問境界を検出
 */
async function detectQuestionBoundariesFallback(pdfBuffer: Buffer): Promise<DetectBoundariesResult> {
  const client = getGeminiClient();
