function readBooleanEnv(name: string, defaultValue: boolean): boolean {
  const value = process.env[name];
  if (value === undefined) return defaultValue;
  const normalized = value.trim().toLowerCase();
  if (['1', 'true', 'yes', 'on'].includes(normalized)) return true;
  if (['0', 'false', 'no', 'off'].includes(normalized)) return false;
  return defaultValue;
}

export function getVisionModel(): string {
  if (visionModelCache) return visionModelCache;

  const model = process.env.GEMINI_VISION_MODEL;
  if (!model) {
    throw new Error('GEMINI_VISION_MODEL environment variable is not set');
  }
  visionModelCache = model;
  return model;
}

export function getParseModel(): string {
  if (parseModelCache) return parseModelCache;

  const model = process.env.GEMINI_PARSE_MODEL || process.env.GEMINI_VISION_MODEL;
  if (!model) {
    throw new Error('GEMINI_PARSE_MODEL または GEMINI_VISION_MODEL のどちらかの環境変数を設定する必要があります');
  }
  parseModelCache = model;
  return model;
}

export function getSplitModel(): string {
  if (splitModelCache) return splitModelCache;

  const model = process.env.GEMINI_SPLIT_MODEL || process.env.GEMINI_VISION_MODEL;
  if (!model) {
    throw new Error('GEMINI_SPLIT_MODEL または GEMINI_VISION_MODEL のどちらかの環境変数を設定する必要があります');
  }
  splitModelCache = model;
  return model;
}

export function isAgenticVisionEnabled(): boolean {
  return readBooleanEnv('GEMINI_AGENTIC_VISION_ENABLED', true);
}

export function isCodeExecutionEnabled(): boolean {
  return readBooleanEnv('GEMINI_CODE_EXECUTION_ENABLED', true);
}

export function getThinkingLevel(): 'low' | 'medium' | 'high' {
  if (thinkingLevelCache) return thinkingLevelCache;
  const value = (process.env.GEMINI_THINKING_LEVEL || 'high').trim().toLowerCase();
  switch (value) {
    case 'low':
      thinkingLevelCache = 'low';
      break;
    case 'medium':
      thinkingLevelCache = 'medium';
      break;
    default:
      thinkingLevelCache = 'high';
      break;
  }
  return thinkingLevelCache;
}

