import { GoogleGenerativeAI, Part } from '@google/generative-ai';
import { GoogleGenAI, ThinkingLevel } from '@google/genai';
import { getSubjectInfo } from '../constants/topic-master';
import type { SolutionApproach } from '../../types/database';
import { extractAndParseJson } from './parser-utils';

/** GEMINI_API_KEY を取得（未設定ならエラー） */
function getApiKey(): string {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) {
    throw new Error('GEMINI_API_KEY is not set. Please add it to your environment variables.');
  }
  return apiKey;
}

let genAI: GoogleGenerativeAI | null = null;

export function getGeminiClient() {
  if (!genAI) {
    genAI = new GoogleGenerativeAI(getApiKey());
  }
  return genAI;
}

let genAINew: GoogleGenAI | null = null;

/** 新SDK (@google/genai) クライアント — thinkingConfig 対応 */
export function getNewSdkClient(): GoogleGenAI {
  if (!genAINew) {
    genAINew = new GoogleGenAI({ apiKey: getApiKey() });
  }
  return genAINew;
}

let visionModelCache: string | null = null;
let parseModelCache: string | null = null;
let splitModelCache: string | null = null;
let thinkingLevelCache: 'low' | 'medium' | 'high' | null = null;

const TOPIC_GRANULARITY_RULES = `【トピック選択ルール - 厳守】
タグは少なく正確に。以下の手順で選択すること。

■ Step 1: まず問題の本質を一言で説明する
「この問題は何の問題か？」を一言で説明してください。

■ Step 2: Step 1 の説明に直接対応するトピックのみ選ぶ
Step 1 の説明に登場するキーワードに対応するトピックだけをマスターリストから選ぶ。
Step 1 に登場しないテーマのトピックは選ばない。

■ 核心テーマ vs 補助的手法
○ 核心 = その大問固有のテーマ。これがなければ別の問題になる
× 補助 = 多くの問題で汎用的に使う計算道具。なくても問題の個性は変わらない
判断:「この問題を知らない人に『何の問題？』と聞かれて答える内容」に含まれるか？
  → 含まれる → タグを付ける
  → 含まれない → タグを付けない

■ その他のルール
- 同じサブ単元（第4階層）のトピックは最も代表的なもの1つだけ選ぶ
- 1つの大問につきトピックは1〜4個を目安とする（多くても5個まで）`;

function readBooleanEnv(name: string, defaultValue: boolean): boolean {
  const value = process.env[name];
  if (value === undefined) return defaultValue;
  const normalized = value.trim().toLowerCase();
  if (['1', 'true', 'yes', 'on'].includes(normalized)) return true;
  if (['0', 'false', 'no', 'off'].includes(normalized)) return false;
  return defaultValue;
}

export function getVisionModel(): string {
  if (visionModelCache) return visionModelCache;

  const model = process.env.GEMINI_VISION_MODEL;
  if (!model) {
    throw new Error('GEMINI_VISION_MODEL environment variable is not set');
  }
  visionModelCache = model;
  return model;
}

export function getParseModel(): string {
  if (parseModelCache) return parseModelCache;

  const model = process.env.GEMINI_PARSE_MODEL || process.env.GEMINI_VISION_MODEL;
  if (!model) {
    throw new Error('GEMINI_PARSE_MODEL または GEMINI_VISION_MODEL のどちらかの環境変数を設定する必要があります');
  }
  parseModelCache = model;
  return model;
}

export function getSplitModel(): string {
  if (splitModelCache) return splitModelCache;

  const model = process.env.GEMINI_SPLIT_MODEL || process.env.GEMINI_VISION_MODEL;
  if (!model) {
    throw new Error('GEMINI_SPLIT_MODEL または GEMINI_VISION_MODEL のどちらかの環境変数を設定する必要があります');
  }
  splitModelCache = model;
  return model;
}

export function isAgenticVisionEnabled(): boolean {
  return readBooleanEnv('GEMINI_AGENTIC_VISION_ENABLED', true);
}

export function isCodeExecutionEnabled(): boolean {
  return readBooleanEnv('GEMINI_CODE_EXECUTION_ENABLED', true);
}

export function getThinkingLevel(): 'low' | 'medium' | 'high' {
  if (thinkingLevelCache) return thinkingLevelCache;
  const value = (process.env.GEMINI_THINKING_LEVEL || 'high').trim().toLowerCase();
  switch (value) {
    case 'low':
      thinkingLevelCache = 'low';
      break;
    case 'medium':
      thinkingLevelCache = 'medium';
      break;
    default:
      thinkingLevelCache = 'high';
      break;
  }
  return thinkingLevelCache;
}

/**
 * 必須の環境変数を取得（未設定の場合はエラー）
 */
function getRequiredEnvVar(name: string): string {
  const value = process.env[name];
  if (!value) {
    throw new Error(`${name} environment variable is not set`);
  }
  return value;
}

/**
 * 科目に応じた解説生成用モデルを取得
 * 全科目 GEMINI_VISION_MODEL (flash) を使用
 */
export function getExplanationModel(subject: string): string {
  return getRequiredEnvVar('GEMINI_VISION_MODEL');
}

export async function ocrPage(imageBuffer: Buffer, mimeType: string = 'image/png'): Promise<string> {
  const client = getGeminiClient();
  const model = client.getGenerativeModel({ model: getVisionModel() });

  const imagePart: Part = {
    inlineData: {
      data: imageBuffer.toString('base64'),
      mimeType,
    },
  };

  const prompt = `この画像は大学入試の数学の問題です。
テキストを正確に文字起こししてください。
数式は LaTeX 形式（$...$ または $$...$$）で記述してください。
図がある場合は [図] と記載してください。
表がある場合は、できる限り再現してください。
箇条書きや段落の構造は維持してください。`;

  const result = await model.generateContent([prompt, imagePart]);
  const response = result.response;
  return response.text();
}

export interface OcrPdfResult {
  text: string;
  pageCount: number;
}

export async function ocrPdf(pdfBuffer: Buffer): Promise<OcrPdfResult> {
  const client = getGeminiClient();
  const model = client.getGenerativeModel({ model: getVisionModel() });

  const pdfPart: Part = {
    inlineData: {
      data: pdfBuffer.toString('base64'),
      mimeType: 'application/pdf',
    },
  };

  const prompt = `この PDF は大学入試の問題です。
全ページのテキストを正確に文字起こししてください。

【ルール】
- 数式は LaTeX 形式（$...$ または $$...$$）で記述してください
- 図がある場合は [図] と記載してください
- 表がある場合は、できる限り再現してください
- 箇条書きや段落の構造は維持してください
- 各ページの区切りには「--- ページ N ---」という形式でマーカーを入れてください（N はページ番号）
- 最後に「【総ページ数: X】」という形式で総ページ数を記載してください`;

  const result = await model.generateContent([prompt, pdfPart]);
  const response = result.response;
  const text = response.text();

  // ページ数を抽出
  const pageCountMatch = text.match(/【総ページ数:\s*(\d+)】/);
  let pageCount: number;
  if (pageCountMatch) {
    pageCount = parseInt(pageCountMatch[1], 10);
  } else if (!text.trim()) {
    // 空のテキストの場合は0ページ
    pageCount = 0;
  } else {
    // フォールバック: ページマーカーをカウント
    const pageMarkers = text.match(/---\s*ページ\s*\d+\s*---/g);
    pageCount = pageMarkers ? pageMarkers.length : 1;
  }

  // 総ページ数マーカーを除去した本文を返す
  const cleanedText = text.replace(/【総ページ数:\s*\d+】\s*$/, '').trim();

  return {
    text: cleanedText,
    pageCount,
  };
}

export interface ParsedQuestion {
  question_number: number;
  question_label: string;
  content: string;
  sub_question_count: number;
  solution_approaches: SolutionApproach[];
  topic_tags: string[];  // Geminiが直接生成（大問単位）
  start_page: number | null;
  end_page: number | null;
}

// Agentic Vision による大問境界検出
export interface QuestionBoundary {
  question_number: number;
  label: string;           // "第1問", "問1", "[1]" など
  start_page: number;
  end_page: number | null; // 次の大問の直前まで（最後の大問はnull可）
}

export interface DetectBoundariesResult {
  questions: QuestionBoundary[];
  total_pages: number;
}

export interface ParseQuestionsResult {
  questions: ParsedQuestion[];
}

/** getThinkingLevel() の返り値を新SDK の ThinkingLevel に変換 */
function toNewSdkThinkingLevel(level: string): ThinkingLevelType {
  switch (level) {
    case 'low': return 'low' as ThinkingLevelType;
    case 'medium': return 'medium' as ThinkingLevelType;
    default: return 'high' as ThinkingLevelType;
  }
}

export async function parseQuestions(fullText: string, subject?: string): Promise<ParseQuestionsResult> {
  const client = getNewSdkClient();
  const modelName = getParseModel();
  const thinkingLevel = toNewSdkThinkingLevel(getThinkingLevel());

  // 科目に応じた情報を取得（targetSubjectとtopicPathsの整合性を保証）
  const subjectInfo = getSubjectInfo(subject || '数学');
  // プロンプトインジェクション対策: JSONテンプレート内で使うためダブルクォートをエスケープ
  const targetSubject = subjectInfo.targetSubject.replace(/"/g, '\\"');
  const { topicPaths, isScience } = subjectInfo;

  // 理系/文系に応じた解法指示
  const approachInstruction = isScience
    ? '考えられる主要な解法を**全て**挙げてください'
    : '主要なアプローチを**1つ**挙げてください';

  const prompt = `あなたは大学入試問題の分析者です。

以下は大学入試問題のOCRテキストです。
大問ごとに分割し、以下のJSON形式で返してください:

{
  "questions": [
    {
      "question_number": 1,
      "question_label": "第1問",
      "content": "問題文...",
      "sub_question_count": 3,
      "topic_tags": ["${targetSubject}/分野/単元/サブ単元/トピック"],
      "solution_approaches": [
        {
          "method": "解法名",
          "steps": ["手順1", "手順2", "..."]
        }
      ],
      "start_page": 1,
      "end_page": 2
    }
  ]
}

【教科判定ルール】
- 現在の教科: ${targetSubject}（${isScience ? '理系科目' : '文系科目'}）
- ${approachInstruction}

【出力ルール】
- 大問の区切りは「第1問」「問1」「[1]」「1.」などのパターンで判断
- 小問は (1), (2), (ア), (イ) などで数える
- start_page, end_page は各大問が何ページ目から何ページ目に存在するかを示す（1始まり）
- OCRテキスト内のページ区切り情報（「--- Page X ---」「ページX」「-X-」等）からページ番号を判定してください
- ページ情報が特定できない場合は null を設定してください

【解法アプローチのルール】
- method: 解法の名称（例：「エネルギー保存則」「微分法による最大・最小」）
- steps: 解法の手順を箇条書きで記載

【トピック選択ルール - 重要】
- topic_tags: 大問全体に対するトピックタグをフルパス形式で記載（大問単位で1〜4個、最大5個）
- 以下のリストに存在するトピックのみを使用してください（リスト外のトピックは絶対に使用しないでください）：
${topicPaths.join('\n')}
- 複数選択可。必ず上記リスト内の表記をそのまま使用してください。
- 上記リストは「${targetSubject}」の教科に対応したトピックです。他の教科のトピックは存在しないため選択できません。

${TOPIC_GRANULARITY_RULES}

- まず各大問について Step 1 で「何の問題か」を考え、Step 2 で対応するタグを選んでください。
- JSONのみを返してください。説明文は不要です。

OCRテキスト:
${fullText}`;

  console.log(`[parseQuestions] model=${modelName}, thinking=${getThinkingLevel()}`);

  const result = await client.models.generateContent({
    model: modelName,
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    config: {
      thinkingConfig: { thinkingLevel },
    },
  });

  const text = result.text;
  if (text === undefined) {
    throw new Error('Gemini returned no text response');
  }

  // usage ログ
  const usage = result.usageMetadata;
  if (usage) {
    console.log(
      `[parseQuestions] usage: prompt=${usage.promptTokenCount} completion=${usage.candidatesTokenCount} total=${usage.totalTokenCount} cached=${usage.cachedContentTokenCount ?? 0}`
    );
  }

  // JSONを抽出・サニタイズ・パース
  const parsed = extractAndParseJson<ParseQuestionsResult>(text);
  // 後処理: topic_tagsをマスタリスト照合でフィルタ
  return postProcessQuestions(parsed, topicPaths);
}

/**
 * Geminiの出力を後処理し、topic_tagsをマスタリストでバリデーション
 * topicPathsが指定された場合、マスタリストに存在するパスのみを残す
 */
function postProcessQuestions(result: ParseQuestionsResult, topicPaths?: string[]): ParseQuestionsResult {
  const topicPathSet = topicPaths ? new Set(topicPaths) : undefined;
  let totalRaw = 0;
  let totalRejected = 0;

  const processed = {
    questions: result.questions.map(q => {
      const rawTags = q.topic_tags || [];

      if (!topicPathSet) {
        return { ...q, topic_tags: rawTags };
      }

      const validTags = [...new Set(rawTags.filter(t => topicPathSet.has(t)))];

      totalRaw += rawTags.length;
      totalRejected += rawTags.length - validTags.length;

      return {
        ...q,
        topic_tags: validTags,
      };
    }),
  };

  if (topicPathSet && totalRejected > 0) {
    console.warn(
      `[postProcessQuestions] マスタリスト照合: ${totalRejected}/${totalRaw}件のトピックパスを除外`
    );
  }

  return processed;
}

/**
 * Gemini APIレスポンスから大問境界情報をパース・整形する
 * @param text - Gemini APIからのレスポンステキスト
 * @param functionName - ログ出力用の関数名
 */
function parseBoundariesResponse(text: string, functionName: string): DetectBoundariesResult {
  // JSONを抽出してパース
  const parsed = extractAndParseJson<{
    questions: Array<{
      question_number: number;
      label: string;
      start_page: number;
    }>;
    total_pages: number;
  }>(text);

  // end_page を計算: 次の大問の start_page - 1（最後の大問は null）
  const questionsWithEndPage: QuestionBoundary[] = parsed.questions.map((q, index) => {
    const nextQuestion = parsed.questions[index + 1];
    const end_page = nextQuestion
      ? nextQuestion.start_page - 1
      : null;

    return {
      question_number: q.question_number,
      label: q.label,
      start_page: q.start_page,
      end_page,
    };
  });

  // 大問が1つも検出されない場合の警告ログ
  if (questionsWithEndPage.length === 0) {
    console.warn(`⚠️ ${functionName}: 大問が1つも検出されませんでした`);
  }

  return {
    questions: questionsWithEndPage,
    total_pages: parsed.total_pages,
  };
}

/**
 * Agentic Vision を使用してPDFから大問の境界を視覚的に検出する
 * Code Execution ツールを使用して画像分析を行う
 *
 * Note: 思考モード（thinkingConfig）は新SDK (@google/genai) で対応済み。
 * 必要に応じて getGeminiGenAIClient() を使用し、
 * config.thinkingConfig.thinkingLevel で思考レベルを設定可能。
 */
export async function detectQuestionBoundaries(pdfBuffer: Buffer): Promise<DetectBoundariesResult> {
  if (!isAgenticVisionEnabled()) {
    return detectQuestionBoundariesFallback(pdfBuffer);
  }

  const client = getGeminiClient();

  // Agentic Vision: Code Executionツールを有効化
  // プロンプトで明示的にPythonコード実行を指示することで有効化される
  const tools = isCodeExecutionEnabled() ? [{ codeExecution: {} }] : undefined;
  const model = client.getGenerativeModel({
    model: getVisionModel(),
    tools,
  });

  const pdfPart: Part = {
    inlineData: {
      data: pdfBuffer.toString('base64'),
      mimeType: 'application/pdf',
    },
  };

  const prompt = `このPDFは大学入試問題です。各大問の開始位置を視覚的に検出してください。

【重要】必ずPythonコードを生成・実行して以下を行ってください：
1. PDFの各ページを画像として取得
2. 「第○問」「問○」「[1]」「1.」などの大問開始パターンを探す
3. 検出した箇所にバウンディングボックス（赤い矩形）を描画
4. 描画結果を確認して検出が正しいか検証

【検出対象パターン】
- 「第1問」「第2問」...
- 「問1」「問2」...
- 「[1]」「[2]」...
- 「1.」「2.」...（大きなフォントで問題の区切りになっているもの）

【出力形式】
検証完了後、以下のJSON形式で返してください：
{
  "questions": [
    { "question_number": 1, "label": "第1問", "start_page": 1 },
    { "question_number": 2, "label": "第2問", "start_page": 3 }
  ],
  "total_pages": 5
}

- 大問が見つからない場合は空配列を返す
- JSONのみを返し、説明は不要`;

  try {
    const result = await model.generateContent([prompt, pdfPart]);
    const response = result.response;
    const text = response.text();

    return parseBoundariesResponse(text, 'detectQuestionBoundaries');
  } catch (error) {
    // Code Executionが失敗した場合のフォールバック処理
    console.error('❌ detectQuestionBoundaries: Agentic Vision処理でエラーが発生しました');
    console.error('Error:', error instanceof Error ? error.message : error);

    // フォールバック: Code Executionなしで再試行
    console.log('🔄 フォールバック: 通常のVision APIで再試行します...');
    return detectQuestionBoundariesFallback(pdfBuffer);
  }
}

/**
 * フォールバック: Code Executionなしで大問境界を検出
 */
async function detectQuestionBoundariesFallback(pdfBuffer: Buffer): Promise<DetectBoundariesResult> {
  const client = getGeminiClient();
  const model = client.getGenerativeModel({ model: getVisionModel() });

  const pdfPart: Part = {
    inlineData: {
      data: pdfBuffer.toString('base64'),
      mimeType: 'application/pdf',
    },
  };

  const prompt = `このPDFは大学入試問題です。各大問の開始位置を検出してください。

【検出対象パターン】
- 「第1問」「第2問」...
- 「問1」「問2」...
- 「[1]」「[2]」...
- 「1.」「2.」...（大きなフォントで問題の区切りになっているもの）

【出力形式】
{
  "questions": [
    { "question_number": 1, "label": "第1問", "start_page": 1 },
    { "question_number": 2, "label": "第2問", "start_page": 3 }
  ],
  "total_pages": 5
}

- 大問が見つからない場合は空配列を返す
- JSONのみを返し、説明は不要`;

  const result = await model.generateContent([prompt, pdfPart]);
  const response = result.response;
  const text = response.text();

  return parseBoundariesResponse(text, 'detectQuestionBoundariesFallback');
}

