content.content:
  1→/**
  2→ * kakomon-generator CLIエントリポイント
  3→ *
  4→ * 処理フロー:
  5→ *   Phase 1+2a: detectQuestions — 問題PDF → Gemini で境界+座標を一括検出
  6→ *   Phase 2b:   splitProblems  — 検出結果 → 画像切り出し+PDF生成（Gemini不使用）
  7→ *   Phase 3:    tagQuestions   — 切り出し画像 → Gemini でトピック付け（--skip-tags で省略可）
  8→ *   Phase 4:    splitAnswers   — 解答PDF → Gemini で解答領域一括検出+切り出し
  9→ */
 10→
 11→import fs from "node:fs/promises";
 12→import path from "node:path";
 13→
 14→import { detectQuestions } from "./phases/detect.js";
 15→import { splitProblems } from "./phases/split.js";
 16→import { tagQuestions } from "./phases/tag.js";
 17→import { splitAnswers } from "./phases/answer.js";
 18→import {
 19→  uploadToR2,
 20→  originalPdfKey,
 21→  problemImageKey,
 22→  problemPdfKey,
 23→  answerPdfKey,
 24→  resolveSubjectKey,
 25→  resolveSubjectName,
 26→} from "./lib/r2.js";
 27→import {
 28→  upsertUniversity,
 29→  createDocument,
 30→  createQuestion,
 31→} from "./lib/supabase.js";
 32→import type {
 33→  AnswerSplitResult,
 34→  DetectedQuestion,
 35→  QuestionBoundary,
 36→  CliOptions,
 37→} from "./types.js";
 38→
 39→/**
 40→ * DetectedQuestion[] から QuestionBoundary[] に変換する
 41→ * Phase 4 (splitAnswers) が従来の QuestionBoundary 形式を必要とするため
 42→ */
 43→function toBoundaries(detected: DetectedQuestion[]): QuestionBoundary[] {
 44→  return detected.map((q) => {
 45→    const pages = q.regions.map((r) => r.page);
 46→    return {
 47→      label: q.label,
 48→      startPage: Math.min(...pages),
 49→      endPage: Math.max(...pages),
 50→    };
 51→  });
 52→}
 53→
 54→async function main(options: CliOptions): Promise<void> {
 55→  const outDir = options.outDir;
 56→  if (outDir) {
 57→    await fs.mkdir(outDir, { recursive: true });
 58→  }
 59→
 60→  // PDF読み込み
 61→  const problemPdf = Buffer.from(await fs.readFile(options.problem));
 62→  const answerPdf = options.answer
 63→    ? Buffer.from(await fs.readFile(options.answer))
 64→    : undefined;
 65→
 66→  console.log(`問題PDF: ${options.problem} (${(problemPdf.length / 1024).toFixed(0)} KB)`);
 67→  if (answerPdf) {
 68→    console.log(`解答PDF: ${options.answer} (${(answerPdf.length / 1024).toFixed(0)} KB)`);
 69→  } else {
 70→    console.log("解答PDF: なし（スキップ）");
 71→  }
 72→  console.log(`科目: ${options.subject}  大学: ${options.university}  年度: ${options.year}`);
 73→  console.log("");
 74→
 75→  // Phase 1+2a: 境界検出+座標の一括取得（1回のGemini API呼び出し）
 76→  console.log("-- Phase 1: 境界検出+座標取得 ---------------------");
 77→  const detectedQuestions = await detectQuestions(problemPdf);
 78→  console.log(`  検出された大問: ${detectedQuestions.length}件\n`);
 79→
 80→  // Phase 2b: 問題の切り出し（Gemini不使用、画像処理のみ）
 81→  console.log("-- Phase 2: 問題切り出し -------------------------");
 82→  const splitResults = await splitProblems(problemPdf, detectedQuestions);
 83→  console.log(`  切り出し完了: ${splitResults.length}件\n`);
 84→
 85→  // Phase 3: トピック付け（切り出し画像 → Gemini Vision）
 86→  // --skip-tags 指定時はスキップ（ローカルで Sonnet によるタグ付けを行う場合）
 87→  let tagResults: import("./types.js").TagResult[] = [];
 88→  if (options.skipTags) {
 89→    console.log("-- Phase 3: トピック付け（スキップ: --skip-tags） --\n");
 90→    tagResults = splitResults.map((s) => ({
 91→      label: s.label,
 92→      questionNumber: s.questionNumber,
 93→      topicTags: [],
 94→    }));
 95→  } else {
 96→    console.log("-- Phase 3: トピック付け -------------------------");
 97→    const subjectName = resolveSubjectName(options.subject);
 98→    tagResults = await tagQuestions(splitResults, subjectName);
 99→    console.log(`  タグ付け完了: ${tagResults.length}件\n`);
100→  }
101→
102→  // Phase 4: 解答の切り出し（解答PDFがある場合のみ）
103→  const boundaries = toBoundaries(detectedQuestions);
104→  let answerResults: AnswerSplitResult[] = [];
105→  if (answerPdf) {
106→    console.log("-- Phase 4: 解答切り出し -------------------------");
107→    answerResults = await splitAnswers(answerPdf, boundaries);
108→    console.log(`  切り出し完了: ${answerResults.length}件\n`);
109→  } else {
110→    console.log("-- Phase 4: 解答切り出し（スキップ: 解答PDFなし） --\n");
111→  }
112→
113→  // ローカル出力（--out-dir 指定時のみ）
114→  if (outDir) {
115→    console.log("-- ローカル出力 ----------------------------------");
116→    for (const split of splitResults) {
117→      const baseName = `${options.year}_${options.examType}_${options.subject}_Q${split.questionNumber}`;
118→      const imgPath = path.join(outDir, `${baseName}.png`);
119→      const pdfPath = path.join(outDir, `${baseName}.pdf`);
120→
121→      await fs.writeFile(imgPath, split.imagePng);
122→      await fs.writeFile(pdfPath, split.pdfBuffer);
123→      console.log(`  ${split.label}: ${imgPath}, ${pdfPath}`);
124→    }
125→
126→    if (answerResults.length > 0) {
127→      for (const ans of answerResults) {
128→        const baseName = `${options.year}_${options.examType}_${options.subject}_A${ans.questionNumber}`;
129→        const pdfPath = path.join(outDir, `${baseName}.pdf`);
130→
131→        await fs.writeFile(pdfPath, ans.pdfBuffer);
132→        console.log(`  ${ans.label} 解答: ${pdfPath}`);
133→      }
134→    }
135→
136→    const tagsJson = tagResults.map((t) => ({
137→      label: t.label,
138→      questionNumber: t.questionNumber,
139→      topicTags: t.topicTags,
140→    }));
141→    const tagsPath = path.join(outDir, "tags.json");
142→    await fs.writeFile(tagsPath, JSON.stringify(tagsJson, null, 2));
143→    console.log(`  タグ: ${tagsPath}\n`);
144→  }
145→
146→  // Phase 5: R2アップロード + Supabase DB書き込み
147→  console.log("-- Phase 5: R2アップロード + DB書き込み ------------");
148→
149→  const { university, year, subject, examType } = options;
150→
151→  // 大学ID・科目キーをASCIIに解決、DB用は日本語名に解決
152→  const universityId = await upsertUniversity(university);
153→  const subjectKey = resolveSubjectKey(subject);
154→  const subjectJa = resolveSubjectName(subject);
155→  console.log(`  大学ID: ${universityId}, 科目キー: ${subjectKey}`);
156→
157→  // オリジナルPDFをR2にアップロード
158→  const problemOrigKey = originalPdfKey(universityId, year, subjectKey, examType, "problem");
159→  const uploadPromises: Promise<unknown>[] = [uploadToR2(problemOrigKey, problemPdf, "application/pdf")];
160→  console.log(`  R2: ${problemOrigKey}`);
161→
162→  let answerOrigKey: string | undefined;
163→  if (answerPdf) {
164→    answerOrigKey = originalPdfKey(universityId, year, subjectKey, examType, "answer");
165→    uploadPromises.push(uploadToR2(answerOrigKey, answerPdf, "application/pdf"));
166→    console.log(`  R2: ${answerOrigKey}`);
167→  }
168→  await Promise.all(uploadPromises);
169→
170→  // 大問ごとのファイルをR2にアップロード
171→  for (const split of splitResults) {
172→    const qn = split.questionNumber;
173→    const imgKey = problemImageKey(universityId, year, subjectKey, examType, qn);
174→    const pdfKey = problemPdfKey(universityId, year, subjectKey, examType, qn);
175→    await Promise.all([
176→      uploadToR2(imgKey, split.imagePng, "image/png"),
177→      uploadToR2(pdfKey, split.pdfBuffer, "application/pdf"),
178→    ]);
179→    console.log(`  R2: ${imgKey}, ${pdfKey}`);
180→  }
181→
182→  if (answerResults.length > 0) {
183→    for (const ans of answerResults) {
184→      const aKey = answerPdfKey(universityId, year, subjectKey, examType, ans.questionNumber);
185→      await uploadToR2(aKey, ans.pdfBuffer, "application/pdf");
186→      console.log(`  R2: ${aKey}`);
187→    }
188→  }
189→
190→  console.log(`  DB: university=${universityId}`);
191→
192→  const docPromises: Promise<string>[] = [
193→    createDocument({
194→      universityId,
195→      year,
196→      subject: subjectJa,
197→      examType,
198→      contentType: "problem",
199→      pdfStoragePath: problemOrigKey,
200→    }),
201→  ];
202→  if (answerOrigKey) {
203→    docPromises.push(
204→      createDocument({
205→        universityId,
206→        year,
207→        subject: subjectJa,
208→        examType,
209→        contentType: "answer",
210→        pdfStoragePath: answerOrigKey,
211→      }),
212→    );
213→  }
214→  const [problemDocId, answerDocId] = await Promise.all(docPromises);
215→  console.log(`  DB: problemDoc=${problemDocId}${answerDocId ? `, answerDoc=${answerDocId}` : ""}`);
216→
217→  const boundaryMap = new Map(boundaries.map((b, i) => [i + 1, b]));
218→
219→  for (const split of splitResults) {
220→    const qn = split.questionNumber;
221→    const tags = tagResults.find((t) => t.questionNumber === qn);
222→    const boundary = boundaryMap.get(qn);
223→
224→    const hasAnswer = answerResults.some((a) => a.questionNumber === qn);
225→    const questionId = await createQuestion({
226→      documentId: problemDocId,
227→      questionNumber: qn,
228→      questionLabel: split.label,
229→      startPage: boundary?.startPage ?? 1,
230→      endPage: boundary?.endPage ?? 1,
231→      topicTags: tags?.topicTags ?? [],
232→      splitPdfPath: problemPdfKey(universityId, year, subjectKey, examType, qn),
233→      splitImagePath: problemImageKey(universityId, year, subjectKey, examType, qn),
234→      answerSplitPdfPath: hasAnswer
235→        ? answerPdfKey(universityId, year, subjectKey, examType, qn)
236→        : null,
237→    });
238→    console.log(`  DB: Q${qn} ${split.label} → ${questionId}`);
239→  }
240→
241→  console.log("\n完了");
242→}
243→
244→// CLI引数パース（commander 導入まではシンプルな実装）
245→const args = process.argv.slice(2);
246→function getArg(name: string): string | undefined {
247→  const idx = args.indexOf(`--${name}`);
248→  return idx !== -1 ? args[idx + 1] : undefined;
249→}
250→
251→const problem = getArg("problem");
252→const answer = getArg("answer");
253→const subject = getArg("subject");
254→const university = getArg("university");
255→const year = getArg("year");
256→const examType = getArg("exam-type");
257→
258→if (!problem || !subject || !university || !year || !examType) {
259→  console.error(
260→    "Usage: npx kakomon-generate --problem <pdf> [--answer <pdf>] --subject <subject> --university <name> --year <year> --exam-type <type>",
261→  );
262→  process.exit(1);
263→}
264→
265→main({
266→  problem,
267→  answer: answer || undefined,
268→  subject,
269→  university,
270→  year: Number(year),
271→  examType: examType as CliOptions["examType"],
272→  outDir: getArg("out-dir"),
273→  skipTags: args.includes("--skip-tags"),
274→}).catch((err) => {
275→  console.error("エラー:", err);
276→  process.exit(1);
277→});
278→

  1→import {
  2→  S3Client,
  3→  GetObjectCommand,
  4→  PutObjectCommand,
  5→} from "@aws-sdk/client-s3";
  6→
  7→/** 科目名（日本語）→ ASCIIキーのマッピング */
  8→const SUBJECT_KEY_MAP: Record<string, string> = {
  9→  数学: "math",
 10→  物理: "physics",
 11→  化学: "chemistry",
 12→  生物: "biology",
 13→  英語: "english",
 14→  国語: "japanese",
 15→};
 16→
 17→/** ASCIIキー → 日本語の逆引きマッピング */
 18→const SUBJECT_KEY_REVERSE: Record<string, string> = Object.fromEntries(
 19→  Object.entries(SUBJECT_KEY_MAP).map(([ja, en]) => [en, ja]),
 20→);
 21→
 22→/** ASCIIキーの集合（高速ルックアップ用） */
 23→const VALID_ASCII_KEYS = new Set(Object.values(SUBJECT_KEY_MAP));
 24→
 25→/**
 26→ * 科目名をASCIIキーに変換する
 27→ * 日本語（"物理"）でもASCIIキー（"physics"）でも受け付ける
 28→ */
 29→export function resolveSubjectKey(subject: string): string {
 30→  // 既にASCIIキーならそのまま返す
 31→  if (VALID_ASCII_KEYS.has(subject)) return subject;
 32→
 33→  // 物理DIなどの派生科目キー（例: physics_di）を許容する
 34→  if (/^[a-z][a-z0-9_]*$/.test(subject)) return subject;
 35→
 36→  // 日本語 → ASCIIキー
 37→  const key = SUBJECT_KEY_MAP[subject];
 38→  if (key) return key;
 39→
 40→  const validJa = Object.keys(SUBJECT_KEY_MAP).join(", ");
 41→  const validEn = Object.values(SUBJECT_KEY_MAP).join(", ");
 42→  throw new Error(`Unknown subject: "${subject}" (valid: ${validJa} / ${validEn})`);
 43→}
 44→
 45→/**
 46→ * ASCIIキーまたは日本語の科目名を日本語に変換する
 47→ */
 48→export function resolveSubjectName(subject: string): string {
 49→  if (SUBJECT_KEY_REVERSE[subject]) return SUBJECT_KEY_REVERSE[subject];
 50→  if (SUBJECT_KEY_MAP[subject]) return subject;
 51→  return subject;
 52→}
 53→
 54→let r2Client: S3Client | null = null;
 55→
 56→function getR2Client(): S3Client {
 57→  if (r2Client) return r2Client;
 58→
 59→  const accountId = process.env.R2_ACCOUNT_ID;
 60→  const accessKeyId = process.env.R2_ACCESS_KEY_ID;
 61→  const secretAccessKey = process.env.R2_SECRET_ACCESS_KEY;
 62→
 63→  if (!accountId || !accessKeyId || !secretAccessKey) {
 64→    throw new Error(
 65→      "R2_ACCOUNT_ID, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY are required",
 66→    );
 67→  }
 68→
 69→  r2Client = new S3Client({
 70→    region: "auto",
 71→    endpoint: `https://${accountId}.r2.cloudflarestorage.com`,
 72→    credentials: {
 73→      accessKeyId,
 74→      secretAccessKey,
 75→    },
 76→  });
 77→
 78→  return r2Client;
 79→}
 80→
 81→const bucketName = process.env.R2_BUCKET_NAME ?? "kakomon";
 82→
 83→/**
 84→ * R2にファイルをアップロードし、ストレージパスを返す
 85→ */
 86→export async function uploadToR2(
 87→  key: string,
 88→  body: Buffer,
 89→  contentType: string,
 90→): Promise<string> {
 91→  const client = getR2Client();
 92→
 93→  await client.send(
 94→    new PutObjectCommand({
 95→      Bucket: bucketName,
 96→      Key: key,
 97→      Body: body,
 98→      ContentType: contentType,
 99→    }),
100→  );
101→
102→  return key;
103→}
104→
105→async function bodyToBuffer(body: unknown): Promise<Buffer> {
106→  if (!body) return Buffer.alloc(0);
107→  if (Buffer.isBuffer(body)) return body;
108→  if (body instanceof Uint8Array) return Buffer.from(body);
109→
110→  // Node.js Readable stream (what we expect in this repo)
111→  if (typeof (body as any)?.[Symbol.asyncIterator] === "function") {
112→    const chunks: Buffer[] = [];
113→    for await (const chunk of body as AsyncIterable<Uint8Array>) {
114→      chunks.push(Buffer.from(chunk));
115→    }
116→    return Buffer.concat(chunks);
117→  }
118→
119→  throw new Error(`Unsupported R2 body type: ${Object.prototype.toString.call(body)}`);
120→}
121→
122→/**
123→ * R2からオブジェクトをダウンロードして Buffer で返す
124→ */
125→export async function downloadFromR2(key: string): Promise<Buffer> {
126→  const client = getR2Client();
127→  const res = await client.send(
128→    new GetObjectCommand({
129→      Bucket: bucketName,
130→      Key: key,
131→    }),
132→  );
133→  return bodyToBuffer(res.Body);
134→}
