  1→#!/usr/bin/env tsx
  2→/**
  3→ * Ingest "add" fixes (download official PDFs -> upload to R2 -> upsert kakomon_documents).
  4→ *
  5→ * This is a deterministic alternative to kakomon-collector for this repo.
  6→ *
  7→ * Usage:
  8→ *   bash -lc 'set -a; source .env; set +a; npx -y tsx@4.19.0 scripts/ingest-add-by-fixes.ts --add-fixes path/to/fixes-add.json --dry-run'
  9→ *   bash -lc 'set -a; source .env; set +a; npx -y tsx@4.19.0 scripts/ingest-add-by-fixes.ts --add-fixes path/to/fixes-add.json --force'
 10→ */
 11→
 12→import { readFileSync, mkdtempSync, rmSync } from "fs";
 13→import { tmpdir } from "os";
 14→import path from "path";
 15→import { spawnSync } from "child_process";
 16→import net from "net";
 17→import { createClient } from "@supabase/supabase-js";
 18→import { uploadToR2 } from "../src/lib/r2";
 19→import { normalizeSubject } from "../src/lib/normalize-subject";
 20→
 21→type FixEntry = {
 22→  url: string;
 23→  university_id: string;
 24→  year: number;
 25→  subject_id: string;
 26→  subject_variant: string | null;
 27→  subject_raw: string;
 28→  subject_display: string;
 29→  exam_type: string;
 30→  exam_variant: string | null;
 31→  exam_type_raw: string;
 32→  content_type: "problem" | "answer";
 33→  is_bundled: boolean;
 34→  bundled_subjects: string[] | null;
 35→  action: "add" | "split";
 36→  r2_path: string;
 37→};
 38→
 39→function getArg(name: string): string | null {
 40→  const idx = process.argv.indexOf(name);
 41→  if (idx >= 0 && process.argv[idx + 1]) return process.argv[idx + 1];
 42→  return null;
 43→}
 44→
 45→function isPrivateOrLocalhost(hostname: string): boolean {
 46→  const h = hostname.toLowerCase();
 47→  if (h === "localhost" || h.endsWith(".localhost") || h.endsWith(".local")) return true;
 48→  const ipType = net.isIP(h);
 49→  if (ipType === 4) {
 50→    const parts = h.split(".").map((x) => parseInt(x, 10));
 51→    if (parts.length !== 4 || parts.some((n) => Number.isNaN(n))) return true;
 52→    const [a, b] = parts;
 53→    if (a === 0 || a === 127) return true;
 54→    if (a === 10) return true;
 55→    if (a === 172 && b >= 16 && b <= 31) return true;
 56→    if (a === 192 && b === 168) return true;
 57→    if (a === 169 && b === 254) return true;
 58→    return false;
 59→  }
 60→  if (ipType === 6) {
 61→    if (h === "::1") return true;
 62→    if (h.startsWith("fe80:")) return true;
 63→    if (h.startsWith("fc") || h.startsWith("fd")) return true;
 64→    return false;
 65→  }
 66→  return false;
 67→}
 68→
 69→function validateHttpUrl(input: string): URL {
 70→  let u: URL;
 71→  try {
 72→    u = new URL(input);
 73→  } catch {
 74→    throw new Error(`Invalid URL: ${input}`);
 75→  }
 76→  if (u.protocol !== "https:" && u.protocol !== "http:") throw new Error(`URL must be http(s): ${input}`);
 77→  if (u.username || u.password) throw new Error(`URL must not include credentials: ${input}`);
 78→  if (isPrivateOrLocalhost(u.hostname)) throw new Error(`Refusing localhost/private host URL: ${input}`);
 79→  return u;
 80→}
 81→
 82→function expectedR2Path(params: {
 83→  university_id: string;
 84→  year: number;
 85→  subject_id: string;
 86→  subject_variant: string | null;
 87→  exam_type: string;
 88→  exam_variant: string | null;
 89→  content_type: "problem" | "answer";
 90→}): string {
 91→  const subjectPart = params.subject_variant ? `${params.subject_id}_${params.subject_variant}` : params.subject_id;
 92→  const examPart = params.exam_variant ? `${params.exam_type}_${params.exam_variant}` : params.exam_type;
 93→  return `${params.university_id}/${params.year}/${subjectPart}/${examPart}/${params.content_type}.pdf`;
 94→}
 95→
 96→function sh(cmd: string, args: string[]) {
 97→  const r = spawnSync(cmd, args, { encoding: "utf8", maxBuffer: 50 * 1024 * 1024 });
 98→  if (r.status !== 0) {
 99→    const msg = (r.stderr || r.stdout || "").trim();
100→    throw new Error(`${cmd} failed: ${cmd} ${args.join(" ")}\n${msg}`);
101→  }
102→  return r.stdout;
103→}
104→
105→async function main() {
106→  const addPath = getArg("--add-fixes");
107→  if (!addPath) {
108→    console.error("Error: --add-fixes is required");
109→    process.exit(1);
110→  }
111→
112→  const dryRun = process.argv.includes("--dry-run");
113→  const force = process.argv.includes("--force");
114→  if (!dryRun && !force) {
115→    console.error("Refusing to run LIVE without --force (use --dry-run first)");
116→    process.exit(1);
117→  }
118→
119→  const sbUrl = process.env.SUPABASE_URL;
120→  const sbKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
121→  if (!sbUrl || !sbKey) {
122→    console.error("SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are required");
123→    process.exit(1);
124→  }
125→  const supabase = createClient(sbUrl, sbKey);
126→
127→  const add = JSON.parse(readFileSync(addPath, "utf8")) as FixEntry[];
128→  const entries = add.filter((e) => e.action === "add");
129→  console.log(`Mode: ${dryRun ? "DRY RUN" : "LIVE"}`);
130→  console.log(`Fixes: ${addPath}`);
131→  console.log(`Entries: ${entries.length}`);
132→
133→  // Uniqueness + path guard
134→  const keys = new Set<string>();
135→  for (const e of entries) {
136→    validateHttpUrl(e.url);
137→    const exp = expectedR2Path({
138→      university_id: e.university_id,
139→      year: e.year,
140→      subject_id: e.subject_id,
141→      subject_variant: e.subject_variant,
142→      exam_type: e.exam_type,
143→      exam_variant: e.exam_variant,
144→      content_type: e.content_type,
145→    });
146→    if (e.r2_path !== exp) {
147→      throw new Error(`Unexpected r2_path (refusing)\n  url=${e.url}\n  got=${e.r2_path}\n  exp=${exp}`);
148→    }
149→    if (keys.has(e.r2_path)) throw new Error(`Duplicate r2_path: ${e.r2_path}`);
150→    keys.add(e.r2_path);
151→  }
152→
153→  const workDir = mkdtempSync(path.join(tmpdir(), "kakomon-ingest-add-"));
154→  console.log(`Workdir: ${workDir}`);
155→  try {
156→    let done = 0;
157→    for (const e of entries) {
158→      done += 1;
159→      console.log(`\n[${done}/${entries.length}] ${e.r2_path}`);
160→      if (dryRun) continue;
161→
162→      const outPdf = path.join(workDir, `${done}.pdf`);
163→      sh("curl", [
164→        "-L",
165→        "--fail",
166→        "-sS",
167→        "-A",
168→        "Mozilla/5.0",
169→        "--max-redirs",
170→        "5",
171→        "--proto",
172→        "=https,http",
173→        "--proto-redir",
174→        "=https,http",
175→        "-o",
176→        outPdf,
177→        "--",
178→        e.url,
179→      ]);
180→      const body = readFileSync(outPdf);
181→      await uploadToR2(e.r2_path, body, "application/pdf");
182→
183→      const { error } = await supabase
184→        .from("kakomon_documents")
185→        .upsert(
186→          {
187→            university_id: e.university_id,
188→            year: e.year,
189→            subject: normalizeSubject(e.subject_id),
190→            subject_variant: e.subject_variant ?? null,
191→            subject_raw: e.subject_raw,
192→            subject_display: e.subject_display,
193→            exam_type: e.exam_type,
194→            exam_type_raw: e.exam_type_raw,
195→            content_type: e.content_type,
196→            pdf_storage_path: e.r2_path,
197→            original_url: e.url,
198→            is_bundled_origin: e.is_bundled ?? false,
199→            updated_at: new Date().toISOString(),
200→          },
201→          { onConflict: "pdf_storage_path" },
202→        );
203→      if (error) throw new Error(`DB upsert failed (${e.r2_path}): ${error.message}`);
204→    }
205→  } finally {
206→    if (!dryRun) rmSync(workDir, { recursive: true, force: true });
207→  }
208→}
209→
210→main().catch((err) => {
211→  console.error(err);
212→  process.exit(1);
213→});
